// MyNCE practice question bank — generated from QuestionBank.swift
const QUESTION_BANK = [{"id": "q001", "text": "A client asks at the first session what information may be shared with others. Which counselor response best reflects ethical informed consent?", "options": ["Promise that nothing discussed in counseling will ever be disclosed.", "Explain confidentiality, its limits, fees, records, counselor credentials, and the client's rights before treatment proceeds.", "Begin treatment first and review paperwork only if the client requests it.", "Provide only the counselor's theoretical orientation because confidentiality is implied."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Informed consent requires clear discussion of the counseling relationship, confidentiality and its limits, records, fees, credentials, and client rights before or at the beginning of services."}, {"id": "q002", "text": "A counselor learns that a client has a specific plan, means, and intent to seriously harm an identifiable person. What is the counselor's best initial ethical action?", "options": ["Wait until the client has acted because intent alone is insufficient.", "Take reasonable protective action consistent with law and agency policy, such as consultation, warning, or contacting authorities.", "Ask the potential victim to attend the client's next session without documenting the concern.", "Maintain confidentiality because the threat occurred in a counseling session."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality has exceptions when there is serious, foreseeable, and imminent risk to an identifiable person. Counselors should follow law, policy, consultation, and documentation."}, {"id": "q003", "text": "A former client sends a counselor a social media friend request. What is the most ethical response?", "options": ["Ignore all future contact from the client without any consideration of clinical needs.", "Accept only if the counselor does not post clinical information.", "Maintain professional boundaries and discuss social media policies if contact with the client resumes.", "Accept the request if the client initiated it."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Social media contact can blur boundaries and expose client privacy. Ethical practice uses clear policies and boundary protection."}, {"id": "q004", "text": "A counselor receives a subpoena for a client's complete record. What should the counselor do first?", "options": ["Destroy psychotherapy notes that could harm the client.", "Consult with the client, supervisor or attorney as appropriate, and release only what is legally required or authorized.", "Call the opposing attorney and verbally summarize the case.", "Immediately send the full file to avoid contempt."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "A subpoena does not automatically authorize full disclosure. Counselors protect confidentiality, seek consultation, and disclose the minimum required information."}, {"id": "q005", "text": "A counselor begins working with a client whose concerns require a specialized treatment in which the counselor has no training. What is the most ethical course?", "options": ["Terminate immediately without referrals to avoid liability.", "Seek supervision, consultation, training, or referral so the client receives competent services.", "Continue because basic counseling skills apply to all presenting problems.", "Tell the client that the treatment is experimental and proceed without consultation."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors practice within the boundaries of competence and must obtain training, supervision, consultation, or make an appropriate referral when needed."}, {"id": "q006", "text": "Which documentation practice is most consistent with ethical record keeping?", "options": ["Document only successful sessions so the record reflects client progress.", "Avoid documentation when a case involves legal risk.", "Include personal opinions about the client to help future providers.", "Record clinically relevant, accurate, timely information while protecting client privacy."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Records should be accurate, timely, clinically relevant, and written with privacy and continuity of care in mind."}, {"id": "q007", "text": "A client asks to see their counseling record. Which counselor response is generally most appropriate?", "options": ["Deny access because counseling records belong only to the counselor.", "Tell the client that records can be reviewed only through a court order.", "Follow applicable law and policy while facilitating access and protecting against serious, foreseeable harm.", "Give the record only after removing all diagnoses."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Clients typically have rights related to access to records, but counselors must follow law, agency policy, and ethical standards regarding privacy and potential harm."}, {"id": "q008", "text": "A counselor is offered an expensive gift by a client near termination. What should the counselor do first?", "options": ["Refuse all gifts without discussion because gifts are always unethical.", "Accept all gifts to avoid offending the client.", "Explore the meaning of the gift, cultural context, potential boundary issues, and agency policy before deciding.", "Accept the gift but do not document the interaction."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Gift decisions require clinical judgment, cultural sensitivity, boundary awareness, documentation, and attention to policy rather than a rigid automatic rule."}, {"id": "q009", "text": "A counselor has strong personal values that conflict with a client's goals. What is the ethical priority?", "options": ["Avoid imposing personal values and seek consultation or referral only when competence or harm is at issue.", "End treatment because value differences automatically prevent counseling.", "Persuade the client to adopt values that support healthier choices.", "Continue while subtly redirecting the client toward the counselor's beliefs."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Counselors respect client autonomy and avoid value imposition. Consultation helps determine how to serve the client ethically."}, {"id": "q010", "text": "A counselor in a small town recognizes that a new client is also the counselor's child's teacher. Which action best addresses the ethical concern?", "options": ["Proceed without mentioning it so the client is not uncomfortable.", "Ask the client to avoid contact at school events.", "Discuss the potential multiple relationship, risks, boundaries, and alternatives before proceeding.", "Refuse services because all multiple relationships are unethical."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Not every multiple relationship is prohibited, but counselors must evaluate potential harm, exploitation, impaired objectivity, and alternatives."}, {"id": "q011", "text": "A counselor suspects child abuse based on a minor client's disclosure. What is the counselor's responsibility?", "options": ["Ask the alleged abuser for clarification before making a report.", "Wait for physical proof before reporting.", "Keep the disclosure confidential because minors have privacy rights.", "Follow mandated reporting laws and document the report and clinical rationale."], "correct": 3, "domain": "Professional Practice and Ethics", "explanation": "Mandated reporting laws require timely reporting of suspected abuse; proof beyond suspicion is not typically the counselor's role."}, {"id": "q012", "text": "Which action best demonstrates ethical use of consultation?", "options": ["Consult only with friends because they are outside the agency hierarchy.", "Share only the information necessary for consultation and protect the client's identity when possible.", "Avoid consultation because it violates confidentiality.", "Disclose the client's full name and history to get the most accurate advice."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Consultation is ethical when used to improve care, but disclosures should be limited and client privacy protected."}, {"id": "q013", "text": "A counselor's personal stress is impairing concentration and judgment in sessions. What is the ethical response?", "options": ["Continue seeing clients because personal problems should not affect professional obligations.", "Disclose the counselor's stress in detail to clients to explain mistakes.", "Seek supervision, reduce impairment, and take steps to protect clients from harm.", "Stop documenting until the counselor feels better."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Counselors monitor impairment and take corrective action, including supervision, self-care, referral, or temporary adjustment of duties."}, {"id": "q014", "text": "A client signs a release of information for coordination with a physician. What should the counselor disclose?", "options": ["The full clinical record because the physician is another health professional.", "Only the diagnosis, even if the release requests treatment information.", "Only information authorized by the release and relevant to the coordination purpose.", "Nothing, because releases do not apply to mental health information."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "A valid release should guide the scope, purpose, recipient, and duration of disclosure; counselors use minimum necessary information."}, {"id": "q015", "text": "A counselor advertises being certified in a treatment approach after attending a one-day introductory workshop. What is the ethical concern?", "options": ["The advertisement may misrepresent the counselor's training and competence.", "Advertising clinical specialties is never permitted.", "Clients are responsible for verifying all counselor credentials.", "Certification is unnecessary if the counselor has clinical experience."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Counselors must accurately represent credentials, training, experience, and competence in public statements."}, {"id": "q016", "text": "A counselor wants to use artificial intelligence to summarize session notes. What ethical step is most important before use?", "options": ["Use the tool if it saves time and delete the summary afterward.", "Verify privacy, consent, security, accuracy, and compliance with law and agency policy.", "Use AI only for clients who are not high risk.", "Enter deidentified notes without informing clients because names are omitted."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Technology use requires attention to confidentiality, informed consent, data security, accuracy, and professional responsibility."}, {"id": "q017", "text": "A client can no longer afford the counselor's fee. What response best reflects ethical practice?", "options": ["Reduce services but avoid documenting the change.", "Discuss options such as fee adjustment, referral, or continuity planning without abandoning the client.", "Continue indefinitely without discussing financial boundaries.", "Terminate immediately because payment is part of informed consent."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors manage fees transparently and avoid client abandonment, especially when financial barriers arise."}, {"id": "q018", "text": "A counselor is asked by an employer to reveal whether an employee-client is attending sessions. What should the counselor do?", "options": ["Deny that the client is receiving services to protect privacy.", "Send attendance records because the employer pays for services.", "Obtain the client's written authorization before confirming attendance, unless another legal exception applies.", "Confirm attendance but not diagnosis."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Even confirming a counseling relationship can disclose protected information. Written authorization is usually required."}, {"id": "q019", "text": "Which practice best protects confidentiality in group counseling?", "options": ["Screen members, explain confidentiality and its limits, and clarify that members are asked but cannot be guaranteed to keep privacy.", "Avoid discussing confidentiality so members can speak freely.", "Guarantee absolute confidentiality because the counselor controls the group.", "Allow members to decide confidentiality rules after the group begins."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Group leaders must clearly explain confidentiality expectations and limits, including the counselor's inability to guarantee member behavior."}, {"id": "q020", "text": "A counselor has a client who repeatedly misses appointments. Which action best avoids abandonment?", "options": ["Close the case without notice after the next missed appointment.", "Review attendance policies, assess barriers, document outreach, and provide referrals if services end.", "Threaten to report the client if attendance does not improve.", "Keep the case open indefinitely without contact."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical termination includes notice, attention to barriers, documentation, and appropriate referral or follow-up planning."}, {"id": "q021", "text": "A counselor is conducting research with clients at the agency. What is the most important ethical safeguard?", "options": ["Use voluntary informed consent and protect clients from coercion or compromised services.", "Use client data without consent if names are removed.", "Require participation because agency clients benefit from research.", "Avoid explaining risks so clients are not discouraged."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Research with clients requires voluntary consent, confidentiality protections, risk disclosure, and avoidance of coercion."}, {"id": "q022", "text": "A counselor receives a complaint from a client about feeling misunderstood because of cultural identity. What is the best ethical response?", "options": ["Refer immediately to avoid discussing culture.", "Invite discussion, seek cultural consultation or training, and repair the counseling relationship without defensiveness.", "Tell the client that cultural issues are outside the treatment goals.", "Explain that the counselor treats all clients the same."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Culturally responsive practice requires humility, openness, consultation, and attention to the client's lived experience."}, {"id": "q023", "text": "Which action is most consistent with ethical supervision?", "options": ["A supervisor focuses only on billing compliance.", "A supervisor primarily provides emotional support and avoids case direction.", "A supervisor monitors client welfare, counselor development, documentation, and scope of practice.", "A supervisor allows supervisees full independence once rapport is established."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Supervision includes gatekeeping, client welfare, professional development, ethical practice, and clinical oversight."}, {"id": "q024", "text": "A client asks the counselor to write a custody recommendation after only individual therapy with one parent. What is the best response?", "options": ["Interview the child once and then write the recommendation.", "Ask the client what recommendation would help the case.", "Clarify role limitations and avoid offering an opinion that exceeds available data or competence.", "Write the recommendation because the counselor knows the client well."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Counselors must avoid role confusion and forensic opinions that exceed their role, data, training, or objectivity."}, {"id": "q025", "text": "During an intake, a client reports depressed mood. Which assessment question most directly evaluates suicide risk?", "options": ["Have you had thoughts of killing yourself, and do you have a plan, intent, or access to means?", "Do you think your sadness comes from childhood issues?", "Have you tried journaling when you feel sad?", "Would you like to work on communication skills?"], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Suicide assessment requires direct inquiry about ideation, plan, intent, means, prior attempts, protective factors, and risk factors."}, {"id": "q026", "text": "A client is alert, oriented, and cooperative but speaks rapidly, reports sleeping two hours nightly, and describes grand business plans. Which MSE area is most clearly indicated?", "options": ["No further assessment is needed because the client is oriented.", "The client should be diagnosed with schizophrenia based on rapid speech alone.", "Only memory and concentration should be assessed.", "Mood, thought process, and possible manic symptoms should be assessed further."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Rapid speech, decreased need for sleep, and grandiosity suggest possible mania or hypomania and require further assessment."}, {"id": "q027", "text": "Which item is most central to a biopsychosocial assessment?", "options": ["Current symptoms, medical factors, family history, social supports, culture, risks, and strengths.", "Only the client's DSM diagnosis and insurance information.", "A list of counselor interpretations made during the first session.", "A personality test score and a treatment contract."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A biopsychosocial assessment integrates biological, psychological, social, cultural, risk, and strength-based data."}, {"id": "q028", "text": "A standardized test yields consistent scores across repeated administrations. Which psychometric property is being described?", "options": ["Validity.", "Reliability.", "Clinical significance.", "Norming."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Reliability refers to consistency of measurement, such as test-retest or internal consistency."}, {"id": "q029", "text": "A depression inventory actually measures depressive symptoms rather than general distress. Which property is best represented?", "options": ["Validity.", "Random error.", "Standard deviation.", "Reliability."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Validity concerns whether an instrument measures what it is intended to measure."}, {"id": "q030", "text": "A counselor uses a screening tool that was not normed with the client's cultural group. What is the best next step?", "options": ["Discard the tool and avoid all formal assessment.", "Use the score as definitive because standardized tools are objective.", "Change the client's answers to fit normative expectations.", "Interpret cautiously and consider cultural, linguistic, and contextual factors before making conclusions."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment interpretation must consider cultural fairness, language, context, norms, and possible bias."}, {"id": "q031", "text": "A client presents with panic attacks and heavy caffeine use. Which assessment priority is most appropriate?", "options": ["Diagnose panic disorder immediately because panic attacks are pathognomonic.", "Assess medical, substance, medication, and lifestyle factors that may mimic or worsen anxiety.", "Begin exposure therapy without further assessment.", "Ignore caffeine because it is not an illicit substance."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differential assessment considers medical and substance-related contributors before final diagnosis and treatment planning."}, {"id": "q032", "text": "Which client statement most strongly suggests a need to assess for psychosis?", "options": ["I feel guilty after arguments.", "I have trouble sleeping before exams.", "I worry that people do not like me.", "I hear voices commenting on my behavior when no one else is present."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Auditory hallucinations, delusions, disorganized speech, or impaired reality testing warrant assessment for psychotic symptoms."}, {"id": "q033", "text": "A client reports intrusive unwanted thoughts and repetitive checking to reduce anxiety. Which area should be assessed further?", "options": ["Antisocial traits, because repetitive checking suggests rule-breaking.", "Obsessive-compulsive symptoms, including obsessions, compulsions, impairment, and avoidance.", "Dissociation, because checking always reflects memory gaps.", "Mania, because repetitive behavior indicates high energy."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Intrusive thoughts and rituals aimed at reducing anxiety are characteristic of obsessive-compulsive presentations."}, {"id": "q034", "text": "A client reports nightmares, avoidance, hypervigilance, and intrusive memories after an assault. Which assessment focus is most indicated?", "options": ["Career interests because trauma symptoms usually reflect work dissatisfaction.", "Eating behaviors because trauma must first be treated nutritionally.", "Trauma-related symptoms, duration, impairment, dissociation, safety, and supports.", "Only psychotic symptoms because nightmares indicate hallucinations."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Trauma assessment examines intrusion, avoidance, arousal, mood/cognition changes, duration, impairment, safety, and supports."}, {"id": "q035", "text": "A counselor screens a client for alcohol use. Which question best assesses hazardous drinking behavior?", "options": ["Do you prefer beer or liquor?", "Do your friends drink more than you do?", "Would you be willing to stop drinking forever today?", "How often and how much do you drink, and what consequences have occurred because of drinking?"], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Substance assessment includes frequency, quantity, consequences, loss of control, tolerance, withdrawal, risk, and readiness to change."}, {"id": "q036", "text": "What is the primary purpose of a Mental Status Examination?", "options": ["To replace a diagnostic interview.", "To assess current functioning, appearance, behavior, mood, thought, cognition, insight, and judgment.", "To provide a complete personality profile.", "To determine a client's childhood attachment style."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "The MSE is a structured snapshot of current psychological functioning and behavioral presentation."}, {"id": "q037", "text": "A client reports elevated mood only after starting a stimulant medication. Which diagnostic principle is most relevant?", "options": ["Diagnose bipolar I disorder whenever elevated mood occurs.", "Consider substance- or medication-induced symptoms in the differential diagnosis.", "Rule out all mood disorders because medication is involved.", "Focus only on family history and ignore medication timing."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differential diagnosis considers whether symptoms are attributable to substances, medications, medical conditions, or another disorder."}, {"id": "q038", "text": "Which factor is a protective factor in suicide risk assessment?", "options": ["Recent major loss.", "Access to lethal means.", "Strong reasons for living and connected social support.", "Previous suicide attempt."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Protective factors may reduce risk, while prior attempts, access to means, and recent losses increase concern."}, {"id": "q039", "text": "A counselor asks a client to describe the problem in the client's own words during intake. What is the primary purpose?", "options": ["To gather the client's subjective experience and presenting concern.", "To avoid asking direct risk questions.", "To determine the counselor's treatment modality.", "To test the client's memory using a standardized method."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Client self-report is central to intake because it clarifies the client's perspective, goals, symptoms, and context."}, {"id": "q040", "text": "Which information is most important before assigning a diagnosis?", "options": ["Symptom pattern, duration, impairment, exclusions, cultural context, and differential diagnosis.", "The client's preferred diagnosis.", "A single test score without clinical interview.", "The counselor's first impression and the client's insurance plan."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Diagnosis should be based on criteria, impairment, duration, context, exclusions, and clinical judgment rather than a single impression."}, {"id": "q041", "text": "A client reports memory gaps, depersonalization, and losing time after trauma reminders. Which assessment area is most relevant?", "options": ["Career indecision.", "Obsessive-compulsive checking.", "Dissociative symptoms and trauma history.", "Specific phobia of animals."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Dissociation can include depersonalization, derealization, amnesia, and identity disruption, especially in trauma contexts."}, {"id": "q042", "text": "A counselor wants to select an assessment for an eight-year-old. What consideration is most important?", "options": ["Whether the assessment is commonly used with adults.", "Developmental appropriateness, validity for age, caregiver input, and cultural context.", "Whether the counselor personally likes the scoring format.", "Whether the child can complete it without any adult support."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment selection must match the client's developmental level, culture, language, presenting concern, and available norms."}, {"id": "q043", "text": "Which finding during intake most strongly suggests need for a higher level of care evaluation?", "options": ["Occasional sadness after a breakup.", "Mild social anxiety before presentations.", "Interest in learning coping skills.", "Current suicidal intent with plan, means, and inability to commit to safety planning."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "High acuity risk, impaired safety, or inability to maintain safety may require emergency evaluation or a higher level of care."}, {"id": "q044", "text": "A client says, 'I cannot stop gambling even though I lost rent money.' Which assessment area should be explored?", "options": ["Only neurological impairment.", "Behavioral addiction symptoms, financial consequences, comorbidity, risk, and readiness to change.", "Only academic functioning.", "Only career values."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Compulsive gambling can involve loss of control, consequences, impairment, comorbidity, and financial or safety risks."}, {"id": "q045", "text": "Which statement best describes clinical screening?", "options": ["A brief process used to identify whether further assessment is indicated.", "A treatment intervention used after termination.", "A complete diagnostic evaluation that replaces intake.", "A legal determination of competence."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Screening is preliminary; positive screens require additional assessment, context, and clinical judgment."}, {"id": "q046", "text": "A counselor notices that a client avoids eye contact. What is the best assessment interpretation?", "options": ["Diagnose social anxiety disorder based solely on eye contact.", "Consider multiple explanations, including culture, anxiety, neurodiversity, trauma, or personal style.", "Confront the client for disrespect.", "Assume the client is being deceptive."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Behavioral observations must be interpreted cautiously and culturally; one behavior rarely supports a diagnosis by itself."}, {"id": "q047", "text": "Which assessment practice is most trauma-informed?", "options": ["Avoid all trauma questions because they may upset the client.", "Explain the purpose of questions, offer choice when possible, and monitor the client's distress and safety.", "Require written trauma narratives during the intake session.", "Ask detailed trauma questions rapidly to complete the form."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Trauma-informed assessment balances needed information with safety, choice, collaboration, empowerment, and pacing."}, {"id": "q048", "text": "A client reports irritability, distractibility, and sleep problems. What is the best diagnostic approach?", "options": ["Avoid diagnosis until the client has completed one year of therapy.", "Diagnose ADHD because distractibility is present.", "Evaluate multiple possible explanations, including anxiety, depression, ADHD, trauma, substance use, and medical factors.", "Diagnose major depression because irritability is always depressive."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Overlapping symptoms require differential diagnosis and assessment of duration, context, impairment, development, and contributing factors."}, {"id": "q049", "text": "A client reports low mood, anhedonia, sleep disturbance, guilt, and impaired concentration for more than two weeks. Which clinical focus is most relevant?", "options": ["Antisocial personality features.", "Major depressive symptoms and suicide risk assessment.", "Specific phobia without functional impairment.", "Normal bereavement with no clinical assessment needed."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "A cluster of depressive symptoms lasting at least two weeks with impairment warrants assessment for depressive disorders and suicide risk."}, {"id": "q050", "text": "A client has panic attacks followed by persistent worry about having more attacks and avoidance of exercise. Which concern is most likely?", "options": ["Schizoid personality disorder.", "Obsessive-compulsive personality disorder.", "Dissociative identity disorder.", "Panic disorder with avoidance related to bodily sensations."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Panic disorder involves recurrent unexpected panic attacks and ongoing concern or behavior change related to attacks."}, {"id": "q051", "text": "A client avoids social events because of fear of being judged or humiliated. Which area of clinical focus best fits?", "options": ["Bipolar symptoms.", "Substance withdrawal.", "Somatic delusions.", "Social anxiety symptoms."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Social anxiety centers on fear of negative evaluation and avoidance of social or performance situations."}, {"id": "q052", "text": "A client washes their hands for hours because of intrusive contamination fears. Which clinical focus is most relevant?", "options": ["Oppositional defiant symptoms involving anger at authority.", "Manic symptoms involving increased goal-directed activity.", "Psychotic symptoms involving thought insertion.", "Obsessive-compulsive symptoms involving obsessions and compulsions."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Obsessions are intrusive unwanted thoughts; compulsions are repetitive behaviors or mental acts used to reduce distress."}, {"id": "q053", "text": "A veteran reports intrusive memories, avoidance, negative mood changes, and hyperarousal after combat. Which clinical focus is most relevant?", "options": ["Posttraumatic stress symptoms.", "Specific learning disorder.", "Normal career stress only.", "Narcissistic personality traits."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "PTSD involves trauma exposure plus intrusion, avoidance, mood/cognition changes, and arousal/reactivity symptoms."}, {"id": "q054", "text": "A client alternates between intense idealization and devaluation of others, fears abandonment, and engages in self-harm. Which area should be assessed?", "options": ["Specific phobia.", "Borderline personality features and safety risk.", "Simple bereavement.", "Mathematics disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Borderline features include instability in relationships, self-image, affect, impulsivity, abandonment fears, and possible self-harm."}, {"id": "q055", "text": "A client reports grandiosity, decreased need for sleep, pressured speech, and risky spending. Which clinical concern should be assessed?", "options": ["Obsessive-compulsive disorder only.", "Dysthymia only.", "Mania or hypomania.", "Adjustment disorder only."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Elevated or irritable mood with increased energy and symptoms such as decreased need for sleep may indicate mania or hypomania."}, {"id": "q056", "text": "A client uses opioids daily and becomes ill when trying to stop. Which clinical issue is most relevant?", "options": ["Opioid use disorder with possible withdrawal risk.", "No clinical concern if use is daily.", "Panic disorder because withdrawal is only anxiety.", "Bipolar disorder because opioids cause mood swings."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Daily use with inability to stop and withdrawal symptoms suggests substance use disorder and requires safety-informed assessment."}, {"id": "q057", "text": "A child repeatedly argues with adults, loses temper, and deliberately annoys others without serious rights violations. Which concern best fits?", "options": ["Conduct disorder with severe aggression by definition.", "Major neurocognitive disorder.", "Panic disorder.", "Oppositional defiant behavior."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Oppositional defiant disorder involves angry/irritable mood, argumentative/defiant behavior, or vindictiveness without the more severe rights violations of conduct disorder."}, {"id": "q058", "text": "An adolescent repeatedly violates rules, steals, and shows aggression toward people and animals. Which concern is most relevant?", "options": ["Dissociative amnesia.", "Conduct-disordered behavior.", "Separation anxiety.", "Cyclothymia."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Conduct disorder involves repetitive violation of rights, norms, or rules, including aggression, destruction, deceit/theft, or serious rule violations."}, {"id": "q059", "text": "A client has persistent restriction of food intake, intense fear of weight gain, and distorted body image. Which clinical focus is most relevant?", "options": ["Anorexia nervosa symptoms and medical risk.", "Pica only.", "Somatic symptom disorder only.", "Generalized anxiety only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Restrictive eating with fear of weight gain and body image disturbance suggests anorexia nervosa and requires medical risk assessment."}, {"id": "q060", "text": "A client has recurrent binge eating followed by self-induced vomiting. Which clinical focus is most relevant?", "options": ["Bulimia nervosa symptoms and medical complications.", "Antisocial personality disorder.", "Brief psychotic disorder.", "Narcolepsy."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Bulimia nervosa involves binge eating with compensatory behaviors and potential electrolyte, dental, and medical risks."}, {"id": "q061", "text": "A client reports excessive worry across work, health, finances, and family most days for months. Which concern best fits?", "options": ["Generalized anxiety symptoms.", "Substance intoxication only.", "Schizophrenia.", "Panic disorder only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Generalized anxiety involves persistent, excessive worry across domains with associated symptoms and impairment."}, {"id": "q062", "text": "A client avoids driving after a car accident even though the client is physically recovered. Which focus should be assessed?", "options": ["Trauma-related avoidance, anxiety, and functional impairment.", "Narcissistic traits.", "Primary psychotic symptoms.", "Career indecision."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Avoidance after trauma can maintain PTSD or anxiety symptoms and should be assessed in context."}, {"id": "q063", "text": "A recently bereaved client cries daily but also experiences moments of connection, meaning, and intact reality testing. Which conceptualization is most appropriate?", "options": ["The client necessarily has major depressive disorder.", "Grief is always pathological after two weeks.", "Counseling should avoid discussing the loss.", "Grief may be a normal response, while monitoring for impairment, risk, and complicated grief."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Grief is not automatically pathological; counselors assess duration, impairment, risk, culture, and meaning."}, {"id": "q064", "text": "A client reports hearing voices, believing neighbors control their thoughts, and difficulty maintaining work. Which clinical focus is most relevant?", "options": ["Simple phobia.", "Career values clarification only.", "Psychotic symptoms and functional impairment.", "Normal spiritual development without assessment."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Hallucinations, delusions, and impaired functioning warrant assessment for psychotic disorders and safety needs."}, {"id": "q065", "text": "A child is inattentive, forgetful, disorganized, and has impairment at school and home. Which area should be assessed?", "options": ["Dissociative identity disorder.", "Antisocial personality disorder.", "Panic disorder.", "Attention-deficit/hyperactivity symptoms across settings."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "ADHD assessment considers inattention and/or hyperactivity-impulsivity, impairment, onset, and presence across settings."}, {"id": "q066", "text": "A client reports intrusive memories and self-blame after sexual assault. Which counseling focus is especially important?", "options": ["Focusing only on career goals.", "Trauma symptoms, safety, shame, support, and empowerment.", "Immediate confrontation of irrationality without stabilization.", "Avoiding all discussion of trauma permanently."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Sexual assault work requires trauma-informed attention to safety, choice, shame, support, and pacing."}, {"id": "q067", "text": "A client is being monitored by a partner who controls money, transportation, and phone access. Which concern should be assessed first?", "options": ["Intimate partner violence, coercive control, and safety planning.", "Workplace stress only.", "Academic procrastination.", "Normal marital conflict."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Coercive control and surveillance can indicate intimate partner violence and require careful, non-escalating safety planning."}, {"id": "q068", "text": "A client reports using alcohol to sleep after trauma. Which clinical focus is most relevant?", "options": ["No concern because alcohol is legal.", "Co-occurring trauma symptoms and substance use.", "Only sleep hygiene, with substance use ignored.", "Career testing before clinical assessment."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Trauma and substance use often co-occur; assessment should address both rather than treating them in isolation."}, {"id": "q069", "text": "A client has chronic pain and increasing hopelessness. Which clinical focus should not be missed?", "options": ["Only intelligence testing.", "A presumption that pain is exaggerated.", "Depression, suicide risk, functioning, medical coordination, and coping.", "Only personality testing."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Chronic pain can interact with mood, functioning, identity, and suicide risk and may require interdisciplinary care."}, {"id": "q070", "text": "A teenager reports cutting to feel relief but denies suicidal intent. What clinical focus remains essential?", "options": ["Ignore risk because the client denies suicidal intent.", "Focus only on punishment by caregivers.", "Nonsuicidal self-injury, emotion regulation, suicide risk, and safety planning.", "Treat it only as attention-seeking."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Nonsuicidal self-injury requires assessment of function, frequency, medical risk, suicidality, emotion regulation, and supports."}, {"id": "q071", "text": "A client reports fear of leaving home because escape may be difficult during panic-like symptoms. Which concern is most relevant?", "options": ["Conduct disorder.", "Agoraphobic avoidance.", "Delusional disorder.", "Obsessive-compulsive personality traits."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Agoraphobia involves fear or avoidance of situations where escape may be difficult or help unavailable if panic-like symptoms occur."}, {"id": "q072", "text": "A client experiences recurrent nightmares and hypervigilance after years of childhood abuse. Which clinical lens is most helpful?", "options": ["Career indecision only.", "A single-session phobia model only.", "Normal development without impairment.", "Complex trauma and its effects on affect regulation, relationships, and self-concept."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Chronic interpersonal trauma can affect affect regulation, relationships, self-concept, trust, and safety."}, {"id": "q073", "text": "An older adult client reports memory decline, medication changes, and sudden confusion. What clinical focus is most important?", "options": ["Assume depression is absent in older adults.", "Differentiate mental health symptoms from medical, medication, delirium, or neurocognitive concerns.", "Avoid medical referral because counseling should remain separate.", "Assume dementia is present and begin grief counseling."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Sudden confusion may indicate delirium or medical issues; older adult assessment should consider medical, medication, mood, and cognitive factors."}, {"id": "q074", "text": "A client who immigrated recently reports sadness, isolation, and identity strain. Which focus is most culturally responsive?", "options": ["Encourage immediate assimilation as the treatment goal.", "Assume symptoms are purely biological.", "Avoid discussing culture to prevent stereotyping.", "Acculturation stress, migration history, supports, discrimination, loss, and resilience."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Migration and acculturation can involve loss, stress, discrimination, identity strain, and resilience."}, {"id": "q075", "text": "A client reports repeated job loss due to conflict with supervisors and rigid perfectionism. Which area may be clinically relevant?", "options": ["Personality patterns, interpersonal functioning, and occupational impairment.", "No clinical issue because perfectionism is always adaptive.", "Specific phobia only.", "Psychosis by default."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Persistent interpersonal and personality patterns can contribute to impairment and may be a focus of assessment."}, {"id": "q076", "text": "A child has separation distress, nightmares about caregivers dying, and refusal to attend school. Which concern is most relevant?", "options": ["Bipolar I disorder.", "Separation anxiety symptoms.", "Narcissistic personality disorder.", "Substance intoxication."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Separation anxiety involves excessive fear concerning separation from attachment figures and can impair school attendance."}, {"id": "q077", "text": "A client experiences obsessions about harming others but finds the thoughts horrifying and avoids knives. What is the best conceptual focus?", "options": ["Antisocial personality disorder by definition.", "Mania because thoughts are fast.", "Intrusive ego-dystonic obsessions and compulsive avoidance in OCD.", "Actual homicidal intent by definition."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "OCD harm obsessions are typically unwanted and distressing; clinicians still assess safety but conceptualize ego-dystonic intrusions carefully."}, {"id": "q078", "text": "A college student reports using stimulants without a prescription to study and needing higher amounts. Which area should be assessed?", "options": ["No concern because the use is for studying.", "Stimulant misuse, tolerance, impairment, medical risk, and academic pressures.", "Only career interests.", "Only learning style preferences."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Nonmedical stimulant use can involve substance use risk, tolerance, health consequences, and academic functioning."}, {"id": "q079", "text": "A client reports persistent fatigue, low mood, and appetite changes after beginning a new medication. What should the counselor consider?", "options": ["Ignoring physical factors because counseling is psychological.", "Medication or medical contributors while continuing mental health assessment.", "A personality disorder diagnosis based on fatigue.", "Terminating counseling until the medication is stopped."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Counselors consider medical and medication factors and coordinate care when symptoms may have physical contributors."}, {"id": "q080", "text": "A client has intense fear of gaining weight but is medically stable. What is still necessary?", "options": ["Delay assessment until the client loses more weight.", "Ongoing assessment of eating disorder severity, medical risk, and appropriate level of care.", "Assume counseling alone is sufficient without medical coordination.", "Avoid discussing food because it may reinforce symptoms."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Eating disorders can carry serious medical risk even before obvious instability; level of care and medical coordination matter."}, {"id": "q081", "text": "A client reports compulsive pornography use that conflicts with values and relationships. What should the counselor assess first?", "options": ["Immediately involve the client's partner without consent.", "Treat the behavior as morally neutral and avoid client values.", "Function, impairment, compulsivity, shame, values, relational impact, and co-occurring concerns.", "Assume the behavior is always an addiction."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Counselors assess behavior function, impairment, distress, values, compulsivity, and relational context without imposing values."}, {"id": "q082", "text": "A client recently lost employment and reports identity loss, shame, and family conflict. Which clinical focus is most relevant?", "options": ["No counseling concern because unemployment is practical.", "Psychotic symptoms by default.", "Adjustment, grief, mood, family stress, financial strain, and coping resources.", "A fixed personality flaw."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Employment loss can create adjustment stress, grief, identity disruption, relational strain, and mood symptoms."}, {"id": "q083", "text": "A client has repeated intrusive health worries despite medical reassurance and frequently checks symptoms online. Which focus is most relevant?", "options": ["Bipolar disorder.", "Intellectual disability.", "Health anxiety and reassurance-seeking patterns.", "Conduct disorder."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Health anxiety often involves preoccupation with illness, checking, reassurance seeking, and persistent distress despite reassurance."}, {"id": "q084", "text": "A client reports episodes of binge eating without compensatory behaviors and feels shame and loss of control. Which clinical focus is most relevant?", "options": ["Anorexia nervosa by definition.", "Binge-eating symptoms, shame, impairment, and medical/psychological factors.", "Specific phobia of food.", "Dissociative identity disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Binge-eating disorder involves recurrent binge episodes with loss of control and distress, without regular compensatory behaviors."}, {"id": "q085", "text": "A client reports flashbacks and panic when smelling smoke after a house fire. Which process is most relevant?", "options": ["Normal career indecision.", "Psychopathic traits.", "Trauma cue reactivity.", "Manic flight of ideas."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Trauma reminders can trigger physiological, emotional, and sensory re-experiencing symptoms."}, {"id": "q086", "text": "A client has persistent conflict with family over caregiving for an aging parent. Which focus may be appropriate?", "options": ["Only substance intoxication.", "No clinical focus because caregiving is not psychological.", "Only individual intelligence testing.", "Family roles, caregiver stress, boundaries, grief, and support resources."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Caregiving can involve role strain, boundaries, grief, burnout, relational conflict, and support needs."}, {"id": "q087", "text": "A client reports being bullied at school and now avoids lunch, has stomachaches, and feels worthless. What focus is most relevant?", "options": ["No intervention because bullying is a peer issue.", "Only career development.", "Only oppositional behavior.", "Bullying impact, safety, anxiety, depression, somatic symptoms, and school supports."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Bullying can affect safety, mood, anxiety, somatic complaints, school attendance, and self-worth."}, {"id": "q088", "text": "A client describes recurrent nightmares after military service and uses anger to keep people away. Which clinical focus is most relevant?", "options": ["Trauma-related arousal, avoidance, relational impact, and coping.", "Narcissistic supply.", "Specific learning disorder.", "Simple academic stress."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "PTSD can include hyperarousal, anger, avoidance, sleep disruption, and interpersonal withdrawal."}, {"id": "q089", "text": "A client experiences low mood every winter with improved mood in spring. Which clinical focus should be considered?", "options": ["Substance withdrawal only.", "Antisocial personality disorder.", "Seasonal pattern of depressive symptoms.", "Schizophrenia by definition."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Seasonal recurrence of depressive symptoms may suggest a seasonal pattern and should be assessed for severity, impairment, and risk."}, {"id": "q090", "text": "A parent reports a child has repetitive restricted interests, sensory sensitivities, and social communication differences. Which focus is most relevant?", "options": ["Conduct disorder by default.", "Dissociative amnesia by default.", "Panic disorder by default.", "Autism spectrum characteristics and functional supports."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Autism assessment considers social communication differences, restricted/repetitive behaviors, sensory patterns, development, and supports."}, {"id": "q091", "text": "A client who survived a natural disaster has insomnia, startle response, and survivor guilt. Which clinical focus is most relevant?", "options": ["Academic achievement only.", "Disaster-related trauma, grief, guilt, and stabilization needs.", "Narcissistic traits only.", "Career indecision only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Disasters can produce trauma symptoms, loss, guilt, instability, and practical recovery needs."}, {"id": "q092", "text": "A client reports sexual pain and anxiety about intimacy after a medical procedure. Which response best reflects an appropriate clinical focus?", "options": ["Assess medical coordination, anxiety, relational impact, consent, and sexual functioning with sensitivity.", "Avoid the topic because sexuality is not part of counseling.", "Assume the problem is entirely psychological.", "Tell the partner to be more patient without assessing the client."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Sexual concerns may involve medical, psychological, relational, trauma, and consent factors and require sensitive assessment."}, {"id": "q093", "text": "A client with a disability reports workplace discrimination and internalized shame. Which clinical focus is most relevant?", "options": ["Disability identity, discrimination, advocacy, coping, and mental health impact.", "Focus exclusively on personality testing.", "Avoid advocacy because counseling is only intrapsychic.", "Assume symptoms are caused only by the disability."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Counselors consider disability-related barriers, stigma, identity, accessibility, advocacy, and mental health."}, {"id": "q094", "text": "A client reports explosive anger followed by remorse and relationship damage. Which focus is clinically relevant?", "options": ["Assume anger is always cathartic and healthy.", "Ignore safety because remorse is present.", "Emotion regulation, triggers, safety, accountability, and interpersonal repair.", "Focus only on intelligence testing."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Problematic anger work assesses triggers, regulation, safety, harm, responsibility, and relational patterns."}, {"id": "q095", "text": "A client has repeated panic-like symptoms only when using cannabis. Which clinical focus is most relevant?", "options": ["No concern because cannabis is legal in some states.", "Substance-induced anxiety symptoms and cannabis use patterns.", "Obsessive-compulsive personality disorder.", "Panic disorder without considering substances."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Substances can induce or worsen anxiety symptoms; assessment should consider timing, dose, frequency, and impairment."}, {"id": "q096", "text": "A client reports chronic emptiness, unstable identity, and impulsive spending. Which clinical area should be assessed?", "options": ["Only specific phobia.", "Only math anxiety.", "Personality functioning, mood, impulsivity, and safety risk.", "Only normal career development."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Chronic emptiness, identity disturbance, and impulsivity may indicate personality-related concerns and require careful assessment."}, {"id": "q097", "text": "A client describes repeated unwanted memories and avoidance after witnessing violence at work. Which focus is most relevant?", "options": ["Dementia.", "Secondary or direct trauma exposure and posttraumatic symptoms.", "Oppositional defiant disorder.", "Normal boredom at work."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Witnessing violence can be traumatic and may produce intrusive memories, avoidance, arousal, and mood changes."}, {"id": "q098", "text": "A client reports gambling, sexual risk-taking, and little sleep during periods of unusually high energy. Which focus should be assessed?", "options": ["Bipolar-spectrum symptoms and risk behaviors.", "Only generalized anxiety.", "Only dependent personality disorder.", "Only adjustment disorder."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Risk-taking with decreased sleep and elevated energy may indicate manic or hypomanic episodes and requires safety assessment."}, {"id": "q099", "text": "A client reports persistent fear of vomiting in public and avoids restaurants. Which clinical focus is most relevant?", "options": ["Schizophrenia.", "Bipolar I disorder.", "Conduct disorder.", "Specific phobia or anxiety-related avoidance with functional impairment."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Specific phobias can involve circumscribed fears that lead to avoidance and functional impairment."}, {"id": "q100", "text": "A client reports grief after a miscarriage and feels isolated because others minimize the loss. Which clinical focus is most appropriate?", "options": ["Interpret the grief as attention-seeking.", "Avoid discussing the loss because it is too private.", "Assume the client should recover immediately.", "Reproductive grief, disenfranchised grief, support, meaning, and mood risk."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Miscarriage can involve profound and sometimes disenfranchised grief; counseling should assess support, meaning, trauma, mood, and risk."}, {"id": "q101", "text": "A client reports persistent shame after religious community rejection. Which focus is clinically relevant?", "options": ["Dismiss the concern because religion is outside counseling.", "Focus only on vocational testing.", "Spiritual/religious injury, identity, support, values, and trauma-related symptoms.", "Tell the client to abandon all religious beliefs."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Spiritual and religious experiences can be clinically significant and should be handled with respect, cultural humility, and client-centered values."}, {"id": "q102", "text": "A client has recurrent checking of locks for hours, causing lateness to work. What is the main clinical impairment?", "options": ["Checking proves the client is responsible and does not need treatment.", "The behavior indicates psychosis by definition.", "The issue is only poor time management.", "Compulsions are consuming time and impairing occupational functioning."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "OCD-related compulsions become clinically significant when time-consuming, distressing, or impairing."}, {"id": "q103", "text": "A client reports emotional numbness, avoidance, and guilt after placing a parent in long-term care. Which focus is most relevant?", "options": ["No counseling concern because care placement is practical.", "Narcissistic personality disorder by default.", "Caregiver grief, role transition, guilt, and coping resources.", "Only substance dependence."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Caregiving transitions can involve grief, guilt, relief, family conflict, and identity changes."}, {"id": "q104", "text": "A client reports persistent worry about deportation, family separation, and safety. Which clinical focus should be prioritized?", "options": ["Avoid discussing legal stress because counselors are not attorneys.", "Tell the client the worry is irrational.", "Contextual stressors, legal vulnerability, trauma, family support, and safety planning.", "Assume paranoia without considering context."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Counselors assess sociopolitical and contextual stressors without mislabeling realistic fears as pathology."}, {"id": "q105", "text": "A client with diabetes reports feeling defeated and skipping medical care. Which focus is clinically relevant?", "options": ["Health-related adjustment, depression, adherence barriers, and care coordination.", "Only career counseling.", "Only personality pathology.", "No counseling focus because diabetes is medical."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Chronic illness affects mood, behavior, identity, and functioning; coordination with medical providers may be important."}, {"id": "q106", "text": "A client reports persistent insomnia, racing thoughts at night, and worry about sleep. Which focus is most relevant?", "options": ["Sleep disturbance, anxiety cycle, routines, and possible medical or substance contributors.", "Psychosis by definition.", "Conduct disorder.", "No clinical relevance."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Sleep problems can interact with anxiety, mood, substances, medical factors, and daily functioning."}, {"id": "q107", "text": "Which treatment goal is written in the most measurable form?", "options": ["Client will use two coping skills to reduce panic-related avoidance from five days per week to two days per week within eight weeks.", "Client will understand anxiety deeply.", "Client will feel better soon.", "Counselor will teach relaxation when possible."], "correct": 0, "domain": "Treatment Planning", "explanation": "Effective treatment goals are specific, measurable, attainable, relevant, and time-linked when appropriate."}, {"id": "q108", "text": "A client with severe alcohol withdrawal risk wants outpatient counseling only. What should the treatment plan prioritize?", "options": ["Weekly insight-oriented counseling without referral.", "Medical evaluation and appropriate level of care before routine outpatient counseling.", "A career assessment to improve motivation.", "Immediate exposure therapy for cravings."], "correct": 1, "domain": "Treatment Planning", "explanation": "Treatment planning must consider safety and level of care; withdrawal risk may require medical management."}, {"id": "q109", "text": "A counselor and client identify depression, isolation, and job loss. What should happen next in collaborative treatment planning?", "options": ["Use the same treatment plan used with all depressed clients.", "Avoid goals until termination.", "Let the insurance diagnosis determine all goals.", "Prioritize goals with the client and link objectives and interventions to the client's needs and strengths."], "correct": 3, "domain": "Treatment Planning", "explanation": "Treatment plans should be collaborative, individualized, diagnosis-informed, culturally responsive, and strength-based."}, {"id": "q110", "text": "A client is in precontemplation about substance use. Which treatment plan objective fits best?", "options": ["Avoid discussing substance use.", "Require daily abstinence logs starting tomorrow.", "Begin relapse prevention for a change the client has already mastered.", "Increase awareness of consequences and explore ambivalence without demanding immediate abstinence."], "correct": 3, "domain": "Treatment Planning", "explanation": "Stages of change guide realistic objectives; precontemplation often begins with awareness, engagement, and ambivalence exploration."}, {"id": "q111", "text": "Which element is essential in a crisis treatment plan for a suicidal client?", "options": ["Only a promise never to feel suicidal again.", "A guarantee that the counselor is available 24 hours a day.", "Warning signs, coping steps, social supports, emergency resources, means safety, and follow-up.", "A long-term career plan before safety is discussed."], "correct": 2, "domain": "Treatment Planning", "explanation": "Crisis planning focuses on actionable safety steps, supports, means safety, emergency contacts, and follow-up."}, {"id": "q112", "text": "A client has PTSD and unstable housing. Which treatment planning principle is most appropriate?", "options": ["Ignore housing because it is not a counseling issue.", "Delay all counseling until housing is permanently resolved.", "Address stabilization and practical barriers while planning trauma treatment at a safe pace.", "Begin intensive trauma exposure immediately regardless of housing instability."], "correct": 2, "domain": "Treatment Planning", "explanation": "Treatment planning considers safety, stabilization, resources, barriers, and readiness before intensive trauma processing."}, {"id": "q113", "text": "What is the best reason to revise a treatment plan?", "options": ["The client disagrees with a diagnosis, so no plan is possible.", "Treatment plans should be rewritten after every session regardless of need.", "New assessment information shows the client's needs, risks, goals, or progress have changed.", "The counselor prefers a different theory this week."], "correct": 2, "domain": "Treatment Planning", "explanation": "Treatment plans are living documents revised when new information, progress, barriers, risk, or goals require changes."}, {"id": "q114", "text": "A client is preparing for discharge after meeting treatment goals. What should the plan include?", "options": ["Relapse prevention, warning signs, supports, follow-up options, and steps for returning if needed.", "Transfer all responsibility to the client's family.", "Immediate termination with no review to promote independence.", "Avoid discussing future problems so the client feels confident."], "correct": 0, "domain": "Treatment Planning", "explanation": "Discharge planning supports maintenance of gains and continuity of care."}, {"id": "q115", "text": "A client wants to reduce anxiety but refuses any mindfulness intervention due to religious concerns. What is the best treatment planning response?", "options": ["Insist on mindfulness because it is evidence-based.", "Collaboratively select acceptable evidence-informed alternatives that respect the client's values.", "Tell the client the concern is irrational.", "Remove anxiety from the treatment plan."], "correct": 1, "domain": "Treatment Planning", "explanation": "Treatment planning should respect client values and use collaborative, culturally responsive intervention selection."}, {"id": "q116", "text": "A counselor writes a plan for a child without input from caregivers or school, despite school impairment. What is the main weakness?", "options": ["The plan lacks relevant system collaboration and collateral information.", "The plan is too measurable.", "The plan uses too many strengths.", "The plan respects confidentiality too much."], "correct": 0, "domain": "Treatment Planning", "explanation": "Child treatment often requires developmentally appropriate collaboration with caregivers, schools, and other systems while respecting consent and confidentiality."}, {"id": "q117", "text": "Which treatment plan objective best matches CBT for depression?", "options": ["Client will uncover all repressed memories within two sessions.", "Client will identify and evaluate three recurring automatic thoughts related to worthlessness each week.", "Client will avoid all negative feelings.", "Client will rely on the counselor for daily reassurance."], "correct": 1, "domain": "Treatment Planning", "explanation": "CBT objectives often target automatic thoughts, behavioral activation, skills practice, and measurable symptom change."}, {"id": "q118", "text": "A client has panic disorder and avoids grocery stores. Which intervention should be considered in the plan?", "options": ["Avoidance of grocery stores until anxiety disappears.", "Dream analysis as the only intervention.", "Daily reassurance calls from the counselor.", "Graduated exposure to feared situations paired with coping and cognitive strategies."], "correct": 3, "domain": "Treatment Planning", "explanation": "Exposure-based interventions reduce avoidance and fear through planned, gradual contact with feared cues or situations."}, {"id": "q119", "text": "A client with bipolar disorder wants counseling but is not connected to medication management. What should the treatment plan consider?", "options": ["Refuse counseling until the client accepts medication.", "Counseling alone always replaces medication needs.", "Coordination or referral for psychiatric evaluation while addressing psychosocial goals.", "Focus only on childhood memories."], "correct": 2, "domain": "Treatment Planning", "explanation": "Bipolar presentations often require coordinated care, risk monitoring, psychoeducation, and psychosocial support."}, {"id": "q120", "text": "What is the best treatment planning response when a client faces transportation barriers?", "options": ["Avoid documenting the barrier.", "Identify barriers and adapt the plan through telehealth, referrals, scheduling, or resource coordination when appropriate.", "Mark the client as resistant.", "Keep the same plan and discharge after one missed session."], "correct": 1, "domain": "Treatment Planning", "explanation": "Barriers to goal attainment should be assessed and addressed through practical, ethical, and clinically appropriate modifications."}, {"id": "q121", "text": "Which plan best reflects trauma-informed care?", "options": ["Emphasize safety, choice, collaboration, empowerment, stabilization, and paced trauma work.", "Avoid client choice to reduce anxiety.", "Require immediate detailed trauma disclosure.", "Focus only on symptoms and ignore strengths."], "correct": 0, "domain": "Treatment Planning", "explanation": "Trauma-informed treatment planning prioritizes safety, choice, collaboration, empowerment, cultural responsiveness, and pacing."}, {"id": "q122", "text": "A client and counselor disagree about treatment goals. What should the counselor do?", "options": ["Explore the disagreement, clarify priorities, and collaboratively revise goals when appropriate.", "Ignore the disagreement and proceed with the original plan.", "End treatment immediately because disagreement predicts failure.", "Use the counselor's goals because the counselor is the expert."], "correct": 0, "domain": "Treatment Planning", "explanation": "Collaborative goal setting strengthens alliance and increases relevance, motivation, and accountability."}, {"id": "q123", "text": "A client with OCD wants reassurance-only sessions. What should the plan address?", "options": ["Reduce reassurance-seeking while building exposure, response prevention, and distress tolerance.", "Avoid exposure because anxiety means treatment is harmful.", "Focus only on interpretation of dreams.", "Provide unlimited reassurance to lower anxiety quickly."], "correct": 0, "domain": "Treatment Planning", "explanation": "For OCD, reassurance can become a compulsion; ERP targets obsessions, compulsions, avoidance, and distress tolerance."}, {"id": "q124", "text": "Which treatment plan is most appropriate for co-occurring depression and alcohol misuse?", "options": ["Delay treatment until the client chooses one problem.", "Integrated planning that addresses mood, substance use, risk, coping, and relapse prevention together.", "Treat alcohol use only and ignore mood symptoms.", "Treat depression only and assume alcohol use will resolve automatically."], "correct": 1, "domain": "Treatment Planning", "explanation": "Co-occurring concerns are often best addressed through integrated, coordinated planning rather than isolated or sequential neglect of one condition."}, {"id": "q125", "text": "A client says, 'I know I need to change, but part of me does not want to give up drinking.' Which response best reflects motivational interviewing?", "options": ["You need to decide today or treatment will not work.", "Let's ignore the part that wants to drink.", "Part of you wants change, and part of you is unsure what life would look like without alcohol.", "Alcohol is clearly destroying your life."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Motivational interviewing uses reflective listening to explore ambivalence and evoke client motivation rather than arguing or confronting prematurely."}, {"id": "q126", "text": "Which counselor statement is an accurate reflection of feeling?", "options": ["Your friend sounds irresponsible.", "Why did you expect your friend to come?", "You should stop relying on unreliable people.", "You sound hurt and disappointed that your friend did not show up."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Reflection of feeling identifies and tentatively names the emotional meaning in the client's message."}, {"id": "q127", "text": "A client gives a long description of several conflicts. Which skill helps organize the material and check understanding?", "options": ["Summarizing.", "Changing the subject.", "Giving advice.", "Interpreting dreams."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Summarizing condenses themes, sequence, emotions, and content to promote clarity and collaboration."}, {"id": "q128", "text": "Which question is most open-ended?", "options": ["Did you argue this week?", "What has this week been like for you since the argument?", "Were you angry or sad?", "Did you use the coping skill?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Open-ended questions invite elaboration and help clients describe experiences in their own words."}, {"id": "q129", "text": "In CBT, what is the primary purpose of identifying automatic thoughts?", "options": ["To prove the client's thoughts are irrational and wrong.", "To avoid discussing behavior.", "To examine how interpretations contribute to emotions and behaviors.", "To uncover repressed impulses only."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "CBT links thoughts, emotions, behaviors, and physiology; automatic thoughts are evaluated and modified when unhelpful."}, {"id": "q130", "text": "A client with panic avoids increased heart rate. Which intervention is commonly used in exposure-based CBT?", "options": ["Provide reassurance until anxiety disappears.", "Avoid all activities that raise heart rate.", "Analyze dreams about panic.", "Interoceptive exposure to feared bodily sensations in a planned and safe way."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Interoceptive exposure helps clients learn that feared sensations are tolerable and not necessarily dangerous."}, {"id": "q131", "text": "In ERP for OCD, what does response prevention mean?", "options": ["Refraining from the compulsion after exposure to an obsessional trigger.", "Avoiding all triggers so anxiety stays low.", "Processing childhood memories before any exposure.", "Replacing every obsession with reassurance."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Response prevention reduces compulsive rituals that maintain the obsession-compulsion cycle."}, {"id": "q132", "text": "A client says, 'I am a total failure because I made one mistake.' Which CBT distortion is most evident?", "options": ["All-or-nothing thinking.", "Classical extinction.", "Thought broadcasting.", "Dissociation."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "All-or-nothing thinking views outcomes in extreme categories rather than balanced degrees."}, {"id": "q133", "text": "Which intervention best represents behavioral activation?", "options": ["Waiting until the client feels motivated before acting.", "Scheduling meaningful or mastery-building activities even before motivation returns.", "Focusing exclusively on childhood interpretation.", "Avoiding activity to conserve emotional energy."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral activation targets the withdrawal cycle by increasing reinforcing, valued, or mastery-based activities."}, {"id": "q134", "text": "A counselor says, 'On one hand you want independence, and on the other you fear disappointing your parents.' Which skill is being used?", "options": ["Closed questioning.", "Double-sided reflection.", "Premature termination.", "Directive advice."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "A double-sided reflection captures both sides of ambivalence without forcing resolution."}, {"id": "q135", "text": "Which response best demonstrates immediacy?", "options": ["Let's skip this topic.", "Your childhood is the only reason you avoid trust.", "You should trust me more.", "I notice that as we talk about trust, you look away and become quieter with me too."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Immediacy uses the here-and-now counseling relationship to explore patterns as they emerge in session."}, {"id": "q136", "text": "Which counselor behavior best supports the therapeutic alliance?", "options": ["Telling the client what goals they should have.", "Avoiding discussion of ruptures.", "Collaboratively setting goals, showing empathy, and agreeing on tasks of counseling.", "Using the same intervention regardless of client feedback."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "The alliance includes bond, agreement on goals, and agreement on tasks."}, {"id": "q137", "text": "A client becomes highly distressed during trauma work. Which intervention is most appropriate first?", "options": ["Pause, orient to safety, use grounding, and assess the client's window of tolerance.", "Tell the client to stop having trauma symptoms.", "Push through the exposure regardless of distress.", "End counseling permanently."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Trauma interventions require pacing, grounding, stabilization, and attention to safety and tolerance."}, {"id": "q138", "text": "Which intervention is most consistent with solution-focused counseling?", "options": ["Ask about exceptions and times when the problem is less intense.", "Analyze transference as the first step.", "Require a full family history before any goals.", "Interpret defense mechanisms only."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Solution-focused counseling emphasizes exceptions, strengths, preferred future, scaling, and small next steps."}, {"id": "q139", "text": "In person-centered counseling, which condition involves being real and transparent within professional boundaries?", "options": ["Interpretation.", "Systematic desensitization.", "Paradoxical intention.", "Congruence or genuineness."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Congruence refers to the counselor's authenticity and genuineness in the therapeutic relationship."}, {"id": "q140", "text": "Which intervention best reflects unconditional positive regard?", "options": ["Avoiding difficult topics.", "Giving compliments after every disclosure.", "Communicating acceptance of the client's worth while still addressing harmful behavior.", "Approving every client choice."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Unconditional positive regard means valuing the person without making acceptance conditional on behavior."}, {"id": "q141", "text": "A client says, 'Nothing ever works.' Which ACT-consistent intervention may help?", "options": ["Focus only on symptom elimination.", "Dispute every negative thought until it disappears.", "Tell the client to avoid all painful feelings.", "Clarify values and identify a committed action the client can take while making room for difficult feelings."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "ACT emphasizes values, acceptance, defusion, present-moment awareness, self-as-context, and committed action."}, {"id": "q142", "text": "Which DBT skill teaches clients to notice emotions, thoughts, and urges without immediately acting on them?", "options": ["Free association.", "Mindfulness.", "Flooding.", "Punishment."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "DBT mindfulness helps clients observe, describe, and participate with awareness and reduced impulsivity."}, {"id": "q143", "text": "A client is overwhelmed by emotion and at risk of impulsive behavior. Which DBT skill area is most immediately relevant?", "options": ["Distress tolerance.", "Dream analysis.", "Career exploration.", "Intelligence testing."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Distress tolerance skills help clients survive crises without making them worse."}, {"id": "q144", "text": "Which intervention best represents psychoeducation?", "options": ["Interpreting all symptoms as resistance.", "Avoiding information so the client discovers everything alone.", "Telling the client exactly what decision to make.", "Teaching a client how anxiety activates the fight-or-flight system and how avoidance maintains fear."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Psychoeducation provides accurate information that increases understanding, self-efficacy, and treatment engagement."}, {"id": "q145", "text": "What is the main purpose of a genogram?", "options": ["To visually map family structure, relationships, patterns, and intergenerational themes.", "To measure blood pressure.", "To replace informed consent.", "To diagnose intelligence."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Genograms help counselors explore family patterns, roles, boundaries, losses, and intergenerational dynamics."}, {"id": "q146", "text": "In Bowen family systems theory, differentiation refers to which capacity?", "options": ["Diagnosing one family member as the sole problem.", "Maintaining a clear sense of self while staying emotionally connected to others.", "Always agreeing with the family to reduce conflict.", "Cutting off all family relationships."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Differentiation involves balancing autonomy and connection without being dominated by emotional reactivity."}, {"id": "q147", "text": "Which intervention is most consistent with narrative therapy?", "options": ["Assume the problem is the client's fixed trait.", "Use punishment to reduce behavior.", "Focus only on symptom checklists.", "Externalize the problem and explore alternative stories of identity and agency."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Narrative therapy separates the person from the problem and thickens preferred identity stories."}, {"id": "q148", "text": "A group member monopolizes discussion. What should the group counselor do?", "options": ["Allow it because confrontation is never appropriate in groups.", "Remove the member immediately without discussion.", "Intervene to protect group process by reflecting the pattern and inviting broader participation.", "Ignore quieter members to avoid embarrassment."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Group leaders manage process, promote safety, and balance participation while respecting members."}, {"id": "q149", "text": "Which group stage is commonly associated with deeper cohesion, risk-taking, and productive work?", "options": ["Pregroup screening stage only.", "Initial orientation stage only.", "Termination stage only.", "Working stage."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "The working stage typically involves trust, cohesion, deeper exploration, feedback, and behavior change."}, {"id": "q150", "text": "A client asks for direct advice about whether to divorce. Which response best fits counseling practice?", "options": ["Tell the client exactly what to do.", "Help the client clarify values, options, risks, supports, and consequences rather than deciding for the client.", "Ask the client's spouse to decide.", "Refuse to discuss the topic."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Counselors support autonomy and decision-making without imposing major life decisions."}, {"id": "q151", "text": "Which response best demonstrates empathy rather than sympathy?", "options": ["You have been carrying this alone for a long time, and it feels exhausting.", "At least things could be worse.", "I feel so sorry for you.", "You should be grateful for what you have."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Empathy communicates understanding of the client's experience from the client's perspective."}, {"id": "q152", "text": "A client says, 'I am fine,' while crying and clenching fists. What skill is most appropriate?", "options": ["Gently reflect the discrepancy between words and nonverbal behavior.", "Change topics to reduce discomfort.", "Ignore nonverbal behavior.", "Accuse the client of lying."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Counselors can use gentle confrontation or reflection to explore discrepancies without shaming the client."}, {"id": "q153", "text": "Which intervention best reflects career counseling assessment?", "options": ["Use one interest score as a final career decision.", "Avoid discussing culture and family expectations.", "Explore interests, values, abilities, personality, labor information, barriers, and life roles.", "Choose the highest-paying career for the client."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Career counseling integrates self-knowledge, occupational information, context, barriers, and decision-making."}, {"id": "q154", "text": "Which counseling response best uses a scaling question?", "options": ["On a scale from 0 to 10, where are you today in your confidence to use that coping skill?", "Are you confident, yes or no?", "You should be at a 10 by now.", "Why are you not confident?"], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Scaling questions assess perception, progress, confidence, motivation, and next steps."}, {"id": "q155", "text": "A client is grieving and says, 'I should be over this by now.' Which intervention is most helpful?", "options": ["Normalize variability in grief while exploring meaning, support, and functioning.", "Avoid discussing the deceased.", "Challenge the client to stop crying.", "Tell the client grief should end after one month."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Grief counseling validates individual and cultural variation while assessing impairment, support, meaning, and risk."}, {"id": "q156", "text": "Which intervention best represents crisis counseling?", "options": ["Delay safety planning until the client is calm.", "Ensure safety, stabilize, identify supports, address immediate needs, and plan next steps.", "Focus only on abstract insight.", "Begin long-term personality reconstruction in the first minutes."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Crisis work prioritizes safety, stabilization, practical support, coping, and connection to resources."}, {"id": "q157", "text": "Which counselor response is most consistent with broaching cultural identity?", "options": ["We should avoid identity because it may be uncomfortable.", "Your culture is probably the main reason for this problem.", "Would it be helpful for us to talk about how culture or identity may shape what you are experiencing here?", "I do not see culture; I treat everyone the same."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Broaching invites culturally relevant discussion with humility and client choice."}, {"id": "q158", "text": "A client repeatedly asks whether the counselor is disappointed in them. Which intervention may be useful?", "options": ["Tell the client the question is irrational.", "Refuse to respond and remain silent for the rest of the session.", "Explore the relational pattern and what it is like to seek reassurance in the counseling relationship.", "Give reassurance every time so the client never feels discomfort."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Patterns that emerge in session can be explored therapeutically while maintaining empathy and boundaries."}, {"id": "q159", "text": "Which intervention best reflects reflective listening?", "options": ["You should stop helping them.", "Have you tried making a spreadsheet?", "You want to protect your family, but you are exhausted from being the one everyone relies on.", "That is codependency."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Reflective listening captures content and emotion to deepen understanding and reduce defensiveness."}, {"id": "q160", "text": "A counselor uses too much self-disclosure. What is the primary risk?", "options": ["Self-disclosure automatically improves alliance.", "The focus may shift from the client's needs to the counselor's experience.", "Self-disclosure is always unethical.", "Clients never benefit from appropriate counselor transparency."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Self-disclosure should be intentional, brief, clinically relevant, and focused on client benefit."}, {"id": "q161", "text": "A client in exposure therapy asks to leave as soon as anxiety rises. What is the therapeutic goal?", "options": ["Help the client remain safely engaged long enough to learn anxiety can decrease or be tolerated without avoidance.", "End treatment because exposure caused anxiety.", "Permit immediate escape every time to prevent discomfort.", "Tell the client anxiety is imaginary."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Exposure works by reducing avoidance and building inhibitory learning or habituation through planned, tolerable contact."}, {"id": "q162", "text": "Which intervention is most consistent with relapse prevention?", "options": ["Assume relapse means treatment failure.", "Identify triggers, warning signs, coping responses, supports, and a plan for lapses.", "Rely only on willpower.", "Avoid discussing triggers to prevent cravings."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Relapse prevention prepares clients for high-risk situations, coping, support, and recovery after lapses."}, {"id": "q163", "text": "In couples counseling, what is a helpful intervention for escalating conflict?", "options": ["Avoid discussing patterns because conflict is private.", "Encourage louder expression until emotions are exhausted.", "Slow the interaction, reflect each partner's experience, and establish ground rules for respectful dialogue.", "Pick the partner who seems more rational and side with them."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Couples work often requires process management, emotional validation, boundaries, and pattern identification."}, {"id": "q164", "text": "Which intervention is most consistent with emotion-focused counseling?", "options": ["Diagnose based only on facial expression.", "Avoid emotion and focus only on logic.", "Help the client access, name, regulate, and transform emotional experience in the relationship context.", "Teach only test-taking strategies."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Emotion-focused approaches emphasize emotional awareness, regulation, attachment needs, and corrective emotional experience."}, {"id": "q165", "text": "A counselor says, 'What would be different tomorrow if a small part of the problem were improved?' Which approach is reflected?", "options": ["Classical psychoanalysis only.", "Intelligence assessment.", "Solution-focused counseling.", "Aversion therapy."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Solution-focused questions help clients imagine preferred outcomes and identify small observable changes."}, {"id": "q166", "text": "Which intervention is most appropriate when a client is dissociating in session?", "options": ["Ask for more graphic trauma details immediately.", "End the session without checking safety.", "Use grounding, orienting to the present, sensory cues, and a calm pace.", "Criticize the client for avoiding feelings."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Dissociation is addressed with grounding, present orientation, stabilization, and safety."}, {"id": "q167", "text": "Which statement best reflects accurate confrontation?", "options": ["You say you want closer friendships, and I also notice you cancel whenever someone invites you out.", "You are sabotaging yourself on purpose.", "You need to stop making excuses.", "Your friends are not the problem; you are."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Confrontation in counseling highlights discrepancies respectfully and invites exploration rather than blame."}, {"id": "q168", "text": "Which intervention best matches Adlerian encouragement?", "options": ["Avoid social context.", "Highlight strengths, effort, belonging, and movement toward useful goals.", "Shame the client into changing.", "Focus only on pathology."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Adlerian counseling emphasizes encouragement, social interest, belonging, goals, and lifestyle patterns."}, {"id": "q169", "text": "A client says, 'I cannot stand this anxiety.' Which ACT skill may be used?", "options": ["Cognitive defusion and acceptance of internal experience while choosing valued action.", "Avoiding all situations that produce anxiety.", "Thought stopping until anxiety is eliminated.", "Convincing the client anxiety is morally wrong."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "ACT helps clients relate differently to thoughts and feelings rather than requiring their elimination before action."}, {"id": "q170", "text": "Which technique pairs relaxation with gradual exposure to feared stimuli?", "options": ["Paradoxical intention only.", "Free association.", "Token economy only.", "Systematic desensitization."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Systematic desensitization combines relaxation training with a gradual fear hierarchy."}, {"id": "q171", "text": "A counselor provides homework to test a client's belief that asking for help will always lead to rejection. What CBT method is this?", "options": ["Transference interpretation.", "Dream analysis.", "Behavioral experiment.", "Flooding without consent."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral experiments test predictions and generate new learning through planned action."}, {"id": "q172", "text": "What is the primary purpose of silence used skillfully in counseling?", "options": ["To make the client uncomfortable enough to disclose.", "To avoid responsibility for guiding the session.", "To punish the client for resistance.", "To give the client space to feel, reflect, and continue at their own pace."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic silence can deepen reflection when used intentionally and attuned to the client."}, {"id": "q173", "text": "Which intervention is most appropriate for a client with limited emotional vocabulary?", "options": ["Interpret every feeling as anger.", "Use feeling lists, body cues, scaling, and reflections to build affect identification.", "Avoid emotional language permanently.", "Tell the client emotions are unimportant."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Emotion identification can be built through psychoeducation, body awareness, language, reflection, and practice."}, {"id": "q174", "text": "A counselor notices a rupture after mispronouncing a client's name. What should the counselor do?", "options": ["Ignore it because mentioning it increases discomfort.", "Acknowledge the mistake, apologize, invite correction, and repair without defensiveness.", "Tell the client the mistake was minor.", "Ask the client to use an easier nickname."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Rupture repair supports alliance, respect, cultural humility, and trust."}, {"id": "q175", "text": "Which intervention best supports a client with social anxiety practicing assertiveness?", "options": ["Tell the client to confront everyone immediately.", "Only explain assertiveness theoretically.", "Role-play a specific conversation and process thoughts, feelings, and skills afterward.", "Avoid practice because anxiety may increase."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "Role-play allows skills rehearsal, feedback, exposure, and confidence-building."}, {"id": "q176", "text": "In MI, what does rolling with resistance mean?", "options": ["Confronting resistance as denial.", "Agreeing that change is impossible.", "Responding to sustain talk without arguing, while exploring autonomy and ambivalence.", "Changing the topic whenever the client disagrees."], "correct": 2, "domain": "Counseling Skills and Interventions", "explanation": "MI avoids power struggles and supports autonomy while eliciting change talk."}, {"id": "q177", "text": "Which response best evokes change talk?", "options": ["Why haven't you fixed this yet?", "What would be better in your life if this problem changed even a little?", "You know this is wrong, don't you?", "Do you promise to change today?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Change talk is elicited through questions about desire, ability, reasons, need, commitment, and steps toward change."}, {"id": "q178", "text": "Which intervention best reflects attachment-informed counseling?", "options": ["Assume attachment style is fixed and unchangeable.", "Focus only on IQ scores.", "Avoid discussing relationships.", "Explore patterns of safety, closeness, threat, and emotion regulation in relationships."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Attachment-informed work considers internal working models, emotional safety, proximity, regulation, and relational patterns."}, {"id": "q179", "text": "A client asks, 'What should I do when anger rises in the moment?' Which skill is most practical?", "options": ["Suppress anger and never discuss it.", "Pause, notice body cues, lower arousal, choose a values-consistent response, and repair if needed.", "Make decisions only while angry.", "Vent anger until it disappears."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Anger interventions often combine arousal regulation, awareness, cognitive appraisal, values, communication, and repair."}, {"id": "q180", "text": "Which intervention best matches grief meaning-making?", "options": ["Insist on a single universal grief stage sequence.", "Avoid memories because they prolong grief.", "Tell the client to replace the relationship quickly.", "Invite the client to explore the continuing significance of the loss and how life is reorganized around it."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Meaning-making approaches explore identity, connection, memory, values, and reconstruction after loss."}, {"id": "q181", "text": "Which counselor action best supports termination?", "options": ["End abruptly to test independence.", "Add new major goals in the final session.", "Avoid discussing termination feelings.", "Review progress, consolidate skills, discuss feelings about ending, and plan future supports."], "correct": 3, "domain": "Counseling Skills and Interventions", "explanation": "Termination includes review, consolidation, relapse prevention, referral if needed, and processing the ending."}, {"id": "q182", "text": "A client repeatedly intellectualizes painful experiences. Which intervention may help?", "options": ["Gently shift from analysis to present emotion, body sensation, and meaning at a tolerable pace.", "Stay only in abstract discussion forever.", "Force intense emotional disclosure immediately.", "Criticize the client for being defensive."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Counselors can respect defenses while inviting fuller emotional processing within the client's window of tolerance."}, {"id": "q183", "text": "Which intervention best helps a client challenge mind reading?", "options": ["Ask for evidence, alternative explanations, and a behavioral test of the prediction.", "Assume the prediction is true.", "Use punishment when the thought appears.", "Tell the client never to think about others."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "CBT addresses mind reading by examining evidence, alternatives, probabilities, and experiments."}, {"id": "q184", "text": "A client needs help communicating a boundary. Which counselor intervention is most appropriate?", "options": ["Teach and rehearse clear, respectful, specific assertive language.", "Advise passive silence to avoid conflict.", "Tell the client to cut off the person immediately.", "Write the message for the client and send it without review."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Assertiveness training includes clear expression, respectful tone, specificity, rehearsal, and attention to safety."}, {"id": "q185", "text": "Which counselor quality is most directly reflected by accurately sensing and communicating a client's emotional experience?", "options": ["Authority.", "Empathy.", "Detachment.", "Defensiveness."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Empathy involves understanding and communicating the client's experience in a way the client can recognize."}, {"id": "q186", "text": "A counselor notices irritation toward a client who reminds them of a family member. Which attribute is most important?", "options": ["Assuming the client caused the irritation.", "Avoidance of supervision.", "Rigid certainty.", "Self-awareness and management of countertransference."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Counselors need self-awareness to recognize personal reactions and prevent them from harming the client."}, {"id": "q187", "text": "Which behavior best reflects cultural humility?", "options": ["Claiming expertise in every culture after one course.", "Avoiding culture to prevent mistakes.", "Treating culture as irrelevant to counseling.", "Remaining open to learning from the client while examining one's own assumptions and power."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Cultural humility includes openness, self-reflection, accountability, and attention to power and context."}, {"id": "q188", "text": "A client describes a choice the counselor strongly disagrees with. Which counselor attribute is most important?", "options": ["Control of the client's decisions.", "Respect for client autonomy and nonjudgmental stance.", "Moral superiority.", "Sarcasm to challenge the client."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Effective counselors respect client dignity and autonomy while addressing risk and consequences when needed."}, {"id": "q189", "text": "Which attribute helps a counselor remain grounded when sessions are emotionally intense?", "options": ["Avoidance of feeling.", "Emotional regulation.", "Impulsivity.", "Overidentification."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Counselor emotional regulation supports presence, attunement, judgment, and client safety."}, {"id": "q190", "text": "A counselor admits a misunderstanding and repairs it with the client. Which attribute is demonstrated?", "options": ["Defensiveness.", "Humility and accountability.", "Perfectionism.", "Emotional cutoff."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Humility and accountability allow counselors to repair alliance ruptures and model respectful responsibility."}, {"id": "q191", "text": "Which counselor attribute is most related to being fully attentive in the session?", "options": ["Distraction.", "Self-promotion.", "Presence.", "Impatience."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Presence involves attentive, grounded, responsive engagement with the client's unfolding experience."}, {"id": "q192", "text": "A counselor continues learning after noticing gaps in competence. Which attribute is demonstrated?", "options": ["Role confusion.", "Grandiosity.", "Complacency.", "Professional reflectiveness and commitment to growth."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Effective counselors reflect on limitations and pursue supervision, consultation, and continuing education."}, {"id": "q193", "text": "Which attribute is most important when working with ambiguous client material?", "options": ["Avoidance of complexity.", "Premature certainty.", "Tolerance for ambiguity and curiosity.", "Need to diagnose immediately."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Counselors often hold complexity without rushing to simplistic conclusions."}, {"id": "q194", "text": "A counselor communicates hope without minimizing the client's pain. Which attribute is being shown?", "options": ["Balanced optimism and respect for suffering.", "Detachment.", "Dismissiveness.", "Toxic positivity."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Hope is therapeutic when it honors reality and supports agency rather than minimizing distress."}, {"id": "q195", "text": "Which attribute protects clients from exploitation in the counseling relationship?", "options": ["Excessive self-disclosure.", "Personal dependence on clients.", "Appropriate professional boundaries.", "Need for client approval."], "correct": 2, "domain": "Core Counseling Attributes", "explanation": "Boundaries protect client welfare, role clarity, and the integrity of the counseling relationship."}, {"id": "q196", "text": "A counselor carefully considers how their identity may affect a client from a marginalized group. Which attribute is most relevant?", "options": ["Colorblindness.", "Certainty.", "Deflection.", "Reflexivity."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Reflexivity involves examining one's social location, assumptions, power, and impact on the counseling relationship."}, {"id": "q197", "text": "Which attribute allows a counselor to stay compassionate while not taking responsibility for every client choice?", "options": ["Differentiated compassion with clear professional limits.", "Rescuing.", "Indifference.", "Emotional fusion."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Counselors can care deeply while maintaining limits, autonomy, and responsibility boundaries."}, {"id": "q198", "text": "A counselor receives critical feedback from a client and becomes curious rather than defensive. Which attribute is demonstrated?", "options": ["Control.", "Fragility.", "Dismissiveness.", "Openness to feedback."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Openness to feedback supports alliance repair, growth, and client-centered responsiveness."}, {"id": "q199", "text": "Which attribute is shown when a counselor consistently honors the client's dignity, even during relapse or setbacks?", "options": ["Paternalism.", "Respect and acceptance of the person.", "Conditional regard.", "Shaming confrontation."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Core counseling attributes include respect, acceptance, and belief in the client's dignity even when behavior needs accountability."}, {"id": "q200", "text": "A counselor balances compassion for clients with regular rest, consultation, and realistic caseload limits. Which attribute is demonstrated?", "options": ["Avoidance of responsibility.", "Overfunctioning as the primary method.", "Martyrdom as competence.", "Sustainable self-care and professional responsibility."], "correct": 3, "domain": "Core Counseling Attributes", "explanation": "Sustainable self-care protects counselor functioning and client welfare."}, {"id": "q201", "text": "A counselor in private practice wants to use a sliding fee scale. Which practice is most ethically sound?", "options": ["Set fees arbitrarily each session based on the counselor's mood.", "Establish a clear, consistent fee policy, discuss it during informed consent, and document agreements with clients.", "Never discuss fees because money talk damages the therapeutic alliance.", "Charge insured clients more than uninsured clients without explanation."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical fee practices require transparency, consistency, and informed consent regarding costs, billing, and any sliding-scale arrangements."}, {"id": "q202", "text": "A client who is no longer in treatment texts a counselor late at night seeking crisis support. The counselor's best first step is to:", "options": ["Ignore the message indefinitely because the relationship has ended.", "Respond therapeutically for free indefinitely to avoid abandonment claims.", "Clarify the limits of availability, assess urgency, and direct the client to appropriate crisis resources or re-engagement procedures.", "Block the number without assessing whether the client is in imminent danger."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Even after termination, counselors should respond appropriately to crisis contact, clarify boundaries, and facilitate access to suitable care rather than abandoning a client in danger."}, {"id": "q203", "text": "Which situation most clearly requires a counselor to obtain a release of information before communicating with a third party?", "options": ["Reporting suspected child abuse as mandated by law.", "Warning an identifiable intended victim when a client makes a serious imminent threat.", "Discussing a competent adult client's progress with their employer for workplace planning.", "Consulting anonymously with a supervisor when no identifying details are disclosed."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Voluntary disclosures to third parties such as employers generally require client authorization, whereas mandated reporting and certain duty-to-protect situations are legal exceptions."}, {"id": "q204", "text": "A counselor wants to barter counseling services for a client's home-repair work. What is the most ethical approach?", "options": ["Barter freely whenever a client cannot pay cash.", "Avoid evaluating exploitation risk because bartering always benefits clients.", "Consider cultural context, potential for exploitation or dual relationships, and agency policy; barter only when it is fair, documented, and not clinically contraindicated.", "Require bartering as a condition of continued treatment."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Bartering can create dual relationships and exploitation risks. Ethical practice evaluates fairness, cultural norms, clinical impact, documentation, and policy before proceeding."}, {"id": "q205", "text": "Which statement best reflects ethical practice when counseling minors?", "options": ["Parents always have unlimited access to every detail of a minor's sessions in all jurisdictions.", "Minors never have confidentiality rights.", "Counselors clarify assent, parental consent, confidentiality limits, and applicable laws with the minor and guardians as appropriate.", "Confidentiality with minors is identical to adult confidentiality in every state."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Work with minors requires attention to consent/assent, developmental capacity, parental rights, confidentiality limits, and state-specific legal requirements."}, {"id": "q206", "text": "A counselor discovers that a colleague is practicing while impaired by substance use and posing a risk to clients. What is the most appropriate ethical action?", "options": ["Ignore the situation to avoid workplace conflict.", "Post the concern on social media so the public is warned.", "Address the concern through appropriate channels such as consultation, reporting to supervisors or licensing boards, and protecting client welfare.", "Confront the colleague only after several clients are harmed."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Counselors have an ethical obligation to protect clients when a colleague's impairment or unethical conduct creates risk, using proper professional channels."}, {"id": "q207", "text": "When providing distance counseling via video, which practice is most consistent with ethical standards?", "options": ["Assume in-person informed consent covers all telehealth issues without further discussion.", "Verify identity and location as appropriate, discuss technology risks and emergency procedures, and ensure competence with the modality.", "Record every session secretly for quality assurance.", "Use any free public Wi-Fi location for sessions because convenience is paramount."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Telehealth ethics include technology competence, privacy and security considerations, emergency planning, identity/location verification, and modality-specific informed consent."}, {"id": "q208", "text": "A counselor is asked to provide a character reference for a current client in a custody dispute. What is the best ethical response?", "options": ["Write a glowing character reference because advocacy always helps clients.", "Serve as both therapist and forensic evaluator to save the client money.", "Avoid dual roles that blur treatment and forensic functions; limit statements to what is appropriate and supported by the counseling role.", "Refuse any documentation requests related to legal matters under all circumstances."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Mixing therapeutic and forensic roles can harm clients and compromise objectivity. Counselors should avoid dual roles and provide only role-appropriate, accurate information."}, {"id": "q209", "text": "Which action best demonstrates ethical multicultural competence?", "options": ["Treating all clients identically because fairness means sameness.", "Assuming the counselor's cultural norms are universal best practice.", "Engaging in ongoing self-awareness, knowledge, and skill development regarding diverse worldviews and adapting practice accordingly.", "Avoiding discussion of culture so clients do not feel different."], "correct": 2, "domain": "Professional Practice and Ethics", "explanation": "Multicultural competence is an ethical responsibility involving continuous self-reflection, cultural knowledge, and culturally responsive counseling skills."}, {"id": "q210", "text": "A standardized test has a reliability coefficient of .92. What does this primarily indicate?", "options": ["The test measures what it claims to measure.", "Scores are relatively consistent or stable across replications under similar conditions.", "The test is free of cultural bias.", "The test has high face validity with all clients."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Reliability refers to consistency or stability of measurement; validity concerns whether the instrument measures the intended construct."}, {"id": "q211", "text": "Which statement best distinguishes criterion-related validity from content validity?", "options": ["Criterion-related validity concerns prediction of or correlation with an external criterion; content validity concerns adequate sampling of the domain of interest.", "They are identical concepts used interchangeably in testing.", "Content validity is only about test-retest stability.", "Criterion-related validity is only about item wording clarity."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Content validity addresses domain coverage; criterion-related validity evaluates relationships with external outcomes or criteria (concurrent or predictive)."}, {"id": "q212", "text": "A client's raw score converts to a percentile rank of 84. Which interpretation is most accurate?", "options": ["The client answered 84% of items correctly.", "The client scored higher than approximately 84% of the norm group.", "The client's IQ is 84.", "The client is in the clinical range for all disorders."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A percentile rank indicates the percentage of the norm group that scored at or below the client's score, not the percentage of items correct."}, {"id": "q213", "text": "During intake, a client reports passive thoughts of death without plan, intent, or means. What is the counselor's best immediate action?", "options": ["Hospitalize the client automatically.", "Ignore the report because there is no plan.", "Conduct a thorough suicide risk assessment, develop a collaborative safety plan as indicated, and document the assessment and plan.", "End the session early to avoid increasing risk by discussing suicide."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Any suicidal ideation warrants structured risk assessment of ideation, plan, intent, means, protective factors, and appropriate safety planning and documentation."}, {"id": "q214", "text": "Which information is most essential when making a differential diagnosis between major depressive disorder and bipolar disorder?", "options": ["Only current sleep hours.", "A careful history of manic or hypomanic episodes, including elevated mood, increased energy, and related impairment or risk.", "Whether the client likes their job.", "Only family income level."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Differentiating unipolar depression from bipolar spectrum disorders requires assessment of past or present mania/hypomania and related symptoms and course."}, {"id": "q215", "text": "A counselor uses an assessment instrument that was normed only on a population demographically unlike the client. What is the primary concern?", "options": ["The test will automatically be more reliable.", "Interpretation may be biased or invalid if norms and cultural context do not fit the client.", "Norms never matter for clinical decisions.", "Only reliability is affected, never validity."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment interpretation must consider norm group appropriateness, cultural context, language, and potential bias to avoid invalid conclusions."}, {"id": "q216", "text": "Which intake question best screens for intimate partner violence safety concerns?", "options": ["Do you argue with your partner sometimes?", "Are you ever afraid of your partner, or has your partner threatened, controlled, or physically hurt you?", "Is your relationship perfect?", "Would your partner like to join all sessions?"], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "IPV screening should be direct, private, and behavior-specific, addressing fear, control, threats, and physical harm while prioritizing safety."}, {"id": "q217", "text": "What is the main purpose of using standardized intake procedures across clients in an agency?", "options": ["To eliminate clinical judgment.", "To ensure consistent collection of essential clinical, risk, and demographic information while supporting ethical and legal documentation.", "To guarantee identical treatment plans for every client.", "To replace rapport building entirely with forms."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Standardized intake supports completeness, consistency, risk screening, and documentation while still allowing individualized clinical judgment."}, {"id": "q218", "text": "A client scores in the clinical range on a depression inventory but denies impairment. What should the counselor do next?", "options": ["Diagnose major depression based solely on the score.", "Discard the inventory because self-report is useless.", "Integrate the score with clinical interview, history, functioning, cultural context, and collateral data as appropriate before concluding.", "Increase the score until it matches the counselor's impression."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Assessment results are one data source; diagnosis and clinical conclusions require multimethod integration rather than sole reliance on a single score."}, {"id": "q219", "text": "Which treatment goal is written in the most measurable and useful form?", "options": ["Client will feel better soon.", "Client will reduce panic attacks from daily to no more than two per week within 8 weeks, tracked by a symptom log.", "Client will understand everything about anxiety.", "Client will work on issues."], "correct": 1, "domain": "Treatment Planning", "explanation": "Effective goals are specific, measurable, achievable, relevant, and time-bound, enabling progress monitoring and collaborative revision."}, {"id": "q220", "text": "A client wants to stop using alcohol but is ambivalent. Which planning approach is most appropriate initially?", "options": ["Insist on immediate abstinence-only goals and terminate if the client resists.", "Collaborate on goals matched to the client's stage of change, using motivational strategies while monitoring safety.", "Write a rigid 12-month plan without client input.", "Avoid goal setting until ambivalence disappears completely."], "correct": 1, "domain": "Treatment Planning", "explanation": "Treatment planning should be collaborative and stage-of-change sensitive, especially when ambivalence is present, while still addressing risk."}, {"id": "q221", "text": "What is the primary purpose of including objectives under a treatment goal?", "options": ["To lengthen paperwork without clinical value.", "To break goals into concrete, stepwise actions or skill targets that guide sessions and evaluate progress.", "To replace informed consent.", "To diagnose the client more quickly."], "correct": 1, "domain": "Treatment Planning", "explanation": "Objectives operationalize goals into actionable steps or skill targets that structure interventions and allow progress evaluation."}, {"id": "q222", "text": "When should a treatment plan be reviewed and updated?", "options": ["Only at termination.", "Never, once written at intake.", "At regular intervals and when there are significant changes in symptoms, goals, risk, or circumstances.", "Only if a supervisor requests it."], "correct": 2, "domain": "Treatment Planning", "explanation": "Treatment plans are living documents that should be revisited as clients progress, goals change, or clinical status shifts."}, {"id": "q223", "text": "A client presents with severe depression and active suicidal planning. Which planning priority is most appropriate?", "options": ["Career exploration before addressing safety.", "Long-term personality restructuring as the first target.", "Stabilization and safety planning, including appropriate level of care, before less urgent goals.", "Focus only on childhood insight work."], "correct": 2, "domain": "Treatment Planning", "explanation": "Safety and stabilization take precedence over lower-priority goals when acute risk is present; level-of-care decisions follow risk severity."}, {"id": "q224", "text": "Which element most strengthens collaborative treatment planning?", "options": ["The counselor unilaterally assigns goals based on theory preference.", "Incorporating the client's values, cultural context, strengths, and preferred outcomes into goals and interventions.", "Using only diagnostic labels without functional goals.", "Avoiding discussion of barriers to treatment."], "correct": 1, "domain": "Treatment Planning", "explanation": "Collaborative planning centers client goals, values, culture, and strengths, which improves engagement, relevance, and outcomes."}, {"id": "q225", "text": "A treatment plan lists 'use CBT' as the only intervention for social anxiety. What is missing for a stronger plan?", "options": ["Nothing; naming a modality is sufficient.", "Specific interventions (e.g., psychoeducation, cognitive restructuring, exposure hierarchy), frequency, and measurable targets.", "A guarantee of cure within two sessions.", "A requirement that the client never feel anxiety."], "correct": 1, "domain": "Treatment Planning", "explanation": "Strong plans specify interventions, not only orientations, and link them to measurable goals, session structure, and progress indicators."}, {"id": "q226", "text": "Which factor is most important when selecting an evidence-based intervention for a client?", "options": ["What the counselor learned most recently in a weekend workshop, regardless of fit.", "Research support, client characteristics and preferences, cultural context, counselor competence, and presenting problem match.", "Only the intervention with the longest name.", "Whatever is trending on social media."], "correct": 1, "domain": "Treatment Planning", "explanation": "Evidence-based practice integrates best available research with clinical expertise and client culture, preferences, and context."}, {"id": "q227", "text": "In case management within a treatment plan, what is the counselor's main role?", "options": ["Providing all medical, housing, and legal services personally.", "Coordinating and linking clients to needed resources while maintaining appropriate boundaries and releases of information.", "Avoiding any coordination with other providers.", "Making all life decisions for the client."], "correct": 1, "domain": "Treatment Planning", "explanation": "Case management coordinates access to services and supports continuity of care without replacing other systems or violating boundaries."}, {"id": "q228", "text": "A client says, 'I feel stuck and hopeless about ever changing.' Which response best demonstrates accurate empathy?", "options": ["You just need to think positive.", "It sounds like change feels out of reach right now and that weight is heavy.", "Have you tried my favorite workbook?", "That is not logical."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Empathic responses reflect the client's emotional experience and meaning without prematurely advising, disputing, or redirecting."}, {"id": "q229", "text": "Which technique is most characteristic of motivational interviewing?", "options": ["Direct confrontation of denial as the primary tool.", "Evoking the client's own reasons for change and rolling with resistance rather than arguing.", "Assigning interpretation of unconscious drives each session.", "Using free association as the main intervention."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "MI emphasizes partnership, acceptance, compassion, and evocation—drawing out client motivation and avoiding unproductive confrontation."}, {"id": "q230", "text": "In cognitive therapy, what is the primary target of cognitive restructuring?", "options": ["Unexamined automatic thoughts, intermediate beliefs, and core beliefs that maintain distress.", "Only muscle tension.", "Only childhood free association.", "Only the counselor's countertransference dreams."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "CBT cognitive work identifies and evaluates automatic thoughts and underlying beliefs that contribute to emotional and behavioral problems."}, {"id": "q231", "text": "A counselor uses an empty-chair dialogue to help a client express unfinished feelings toward a parent. This technique is most associated with which approach?", "options": ["Classical psychoanalysis.", "Gestalt therapy.", "Behavioral contingency management.", "Trait-and-factor career counseling only."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Empty-chair and other experiential experiments are hallmark Gestalt methods for working with unfinished business and present-centered awareness."}, {"id": "q232", "text": "Which statement best describes active listening in counseling?", "options": ["Waiting silently to give advice.", "Attending fully and using skills such as paraphrase, reflection, clarifying questions, and summarization to convey understanding.", "Repeating the client's last word only.", "Taking detailed notes while avoiding eye contact."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Active listening combines attending behavior with verbal skills that check and communicate understanding of content and affect."}, {"id": "q233", "text": "During the working stage of a counseling group, members confront one another and give feedback. What is the leader's most appropriate function?", "options": ["Suppress all conflict immediately.", "Facilitate safe, constructive feedback, maintain norms, and help members process interpersonal learning.", "Leave the group so members lead entirely without structure.", "Focus only on individual lectures."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "In the working stage, leaders support cohesion, norms, and therapeutic factors while facilitating productive interpersonal work and safety."}, {"id": "q234", "text": "A client catastrophizes about a job interview. Which intervention is most consistent with REBT?", "options": ["Encourage free association about early oral stage conflicts.", "Identify and vigorously dispute irrational beliefs, then replace them with more rational, flexible beliefs.", "Use only unconditional positive regard without cognitive focus.", "Prescribe medication as the sole intervention."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "REBT targets irrational beliefs through disputation and development of rational, preferential (rather than absolute) beliefs."}, {"id": "q235", "text": "Which counseling skill is most useful when a client gives vague, global statements about their problem?", "options": ["Immediate advice-giving.", "Concrete, open questions and requests for specific examples to increase clarity.", "Changing the subject to reduce discomfort.", "Interpreting dreams right away."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Concreteness helps clients move from vague descriptions to specific situations, feelings, and behaviors that can be assessed and treated."}, {"id": "q236", "text": "A solution-focused counselor asks, 'If a miracle happened overnight and your problem was solved, what would be different tomorrow?' This is primarily used to:", "options": ["Diagnose personality disorders.", "Elicit preferred future details and identify signs of progress and goals.", "Establish free association.", "Measure IQ."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "The miracle question helps clients articulate a preferred future, which guides goal setting and identification of small solvable steps."}, {"id": "q237", "text": "According to Super's life-span, life-space theory, career development is best understood as:", "options": ["A one-time occupational choice in adolescence only.", "A lifelong process involving self-concept development and multiple life roles across stages.", "Determined solely by parental occupation.", "Irrelevant after age 25."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Super emphasized career as a lifelong developmental process shaped by evolving self-concept and roles across the life span."}, {"id": "q238", "text": "Holland's RIASEC model is primarily used to:", "options": ["Diagnose major depressive disorder.", "Match personality/interest types with congruent work environments.", "Measure working memory capacity.", "Replace all clinical interviews."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Holland's typology links six personality/interest types to corresponding occupational environments to support career fit and exploration."}, {"id": "q239", "text": "A client in early recovery from opioid use reports intense craving after seeing old using friends. Which clinical response is most appropriate?", "options": ["Shame the client for residual craving.", "Normalize craving as common, assess relapse risk, strengthen coping and support, and review the recovery plan.", "Encourage reuniting with using friends to test willpower.", "Assume treatment has failed permanently."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Craving is common in recovery; counselors assess risk, reinforce coping skills, support networks, and recovery planning without moralizing."}, {"id": "q240", "text": "Which statement best reflects a trauma-informed counseling stance?", "options": ["Assume all clients are fabricating trauma.", "Prioritize safety, trustworthiness, choice, collaboration, and empowerment while recognizing the impact of trauma.", "Force detailed trauma narrative in session one for every client.", "Avoid any discussion of culture or power."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Trauma-informed care emphasizes safety, trust, collaboration, empowerment, and cultural sensitivity rather than coercive or invalidating practices."}, {"id": "q241", "text": "A couple reports repeated pursuer–distancer cycles during conflict. Which systems-informed focus is most relevant?", "options": ["Identifying only one 'sick' partner as the sole problem.", "Exploring interactional patterns, circular causality, and each partner's role in the cycle.", "Ignoring relationship process and treating only individual diagnoses separately forever.", "Recommending separation without assessment."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Systems perspectives examine reciprocal patterns and circular processes rather than linear blame of a single identified patient."}, {"id": "q242", "text": "Erikson's stage of identity versus role confusion is most associated with which developmental period?", "options": ["Infancy.", "Adolescence.", "Middle adulthood only.", "Late adulthood exclusively."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Erikson linked identity versus role confusion primarily to adolescence, when consolidating a coherent sense of self is central."}, {"id": "q243", "text": "A client from a collectivist cultural background prioritizes family harmony over individual preferences in career choice. A culturally responsive counselor would most likely:", "options": ["Pathologize the client as dependent and enmeshed.", "Explore the client's values, family context, and bicultural pressures without imposing individualistic career norms as the only healthy option.", "Refuse to discuss family influence.", "Require the client to cut contact with family immediately."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Culturally responsive practice respects diverse value systems, including collectivist priorities, while helping clients navigate conflicts and goals."}, {"id": "q244", "text": "Which feature is most characteristic of grief that may need clinical attention beyond typical bereavement support?", "options": ["Sadness in the weeks after a death.", "Persistent functional impairment, intense yearning or preoccupation, or complicated grief features lasting well beyond culturally expected timelines.", "Talking about the deceased occasionally.", "Attending a memorial service."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "While grief is normal, prolonged severe impairment, complicated grief features, or safety concerns may warrant more intensive clinical intervention."}, {"id": "q245", "text": "A school-age child is referred for inattention, hyperactivity, and academic decline. What should a counselor prioritize in clinical focus?", "options": ["Adult-only diagnostic criteria without developmental context.", "Comprehensive assessment across settings, ruling out trauma, sleep, learning, medical, and environmental contributors, and coordinating with caregivers/school as appropriate.", "Immediate long-term psychodynamic therapy only.", "Ignoring school data as irrelevant."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Child attention concerns require multi-setting assessment and differential consideration of medical, learning, trauma, and environmental factors."}, {"id": "q246", "text": "A counselor notices irritation toward a client who reminds them of a family member. Which attribute is most needed next?", "options": ["Denial that personal reactions ever occur.", "Self-awareness and use of supervision/consultation to manage countertransference.", "Immediate termination without reflection.", "Venting irritation to the client as authenticity."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Self-awareness and appropriate use of supervision help counselors manage countertransference so personal reactions do not harm the client."}, {"id": "q247", "text": "Which counselor quality is most closely associated with Rogers' necessary and sufficient conditions?", "options": ["Unconditional positive regard, empathy, and congruence.", "Authoritarian control and expert one-upmanship.", "Frequent advice-giving and persuasion.", "Emotional distance and neutrality only."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Person-centered theory emphasizes congruence (genuineness), unconditional positive regard, and empathic understanding as core facilitative conditions."}, {"id": "q248", "text": "A counselor admits a mistake about a scheduling error and repairs the rupture. Which attribute is demonstrated?", "options": ["Incompetence.", "Humility, accountability, and commitment to the alliance.", "Weak boundaries.", "Overidentification."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Acknowledging errors and repairing ruptures reflects professionalism, humility, and investment in a trustworthy therapeutic relationship."}, {"id": "q249", "text": "Which behavior best reflects professional humility?", "options": ["Claiming expertise in all clinical areas.", "Recognizing limits of knowledge, seeking consultation, and remaining open to learning from clients and colleagues.", "Avoiding continuing education.", "Dismissing client feedback as resistance always."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Humility includes knowing one's limits, valuing consultation and learning, and remaining open rather than assuming omniscience."}, {"id": "q250", "text": "A counselor sits with a client's intense grief without rushing to fix it. Which attribute is most evident?", "options": ["Emotional presence and capacity to tolerate client affect.", "Avoidance of clinical responsibility.", "Lack of intervention skills.", "Disinterest in outcomes."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Therapeutic presence includes staying emotionally available with painful affect rather than prematurely shutting it down with advice or distraction."}, {"id": "q251", "text": "Which attribute most supports ethical boundary maintenance?", "options": ["People-pleasing at all costs.", "Clarity about professional role, self-awareness of pulls to overstep, and consistent limit-setting for client welfare.", "Rigid coldness in every interaction.", "Sharing all personal problems to equalize the relationship."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Healthy boundaries require role clarity, self-awareness, and consistent limits that protect the counseling relationship and client welfare."}, {"id": "q252", "text": "A counselor regularly examines how privilege and bias may affect clinical judgment. This primarily reflects:", "options": ["Unnecessary political activity.", "Cultural humility and reflective practice.", "A boundary violation.", "Diagnostic overreach."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Cultural humility involves ongoing self-examination of bias, power, and privilege and their influence on the counseling relationship."}, {"id": "q253", "text": "Which quality best describes genuineness (congruence) in counseling?", "options": ["Saying whatever the counselor thinks without filters or ethics.", "Alignment between the counselor's internal experience and professional communication in a helpful, boundaried way.", "Never showing any emotion.", "Acting like a blank screen at all times."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Genuineness is authentic, congruent presence that remains professionally appropriate rather than unfiltered self-disclosure or total blankness."}, {"id": "q254", "text": "A counselor continues learning after licensure through consultation groups and training. Which attribute is demonstrated?", "options": ["Imposter syndrome only.", "Commitment to professional growth and competence.", "Dependency on others for all decisions.", "Avoidance of independent practice."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Ongoing learning, consultation, and skill development reflect a professional commitment to competence and client welfare beyond initial licensure."}, {"id": "q255", "text": "A counselor begins a romantic relationship with a former client three weeks after termination. Which ethical principle is most clearly violated?", "options": ["Autonomy only, because the client chose freely.", "Avoiding harmful dual/sexual relationships and protecting former clients from exploitation.", "Justice, because fees were unpaid.", "Fidelity to the insurance company."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Sexual or romantic relationships with current clients are prohibited, and relationships with former clients require careful consideration of exploitation risk and applicable ethical standards and waiting periods."}, {"id": "q256", "text": "Which practice best protects client confidentiality in an open office suite?", "options": ["Discussing cases loudly so colleagues can learn.", "Using soundproofing or white noise, private spaces for sessions, and secure storage of records.", "Leaving charts face-up on the reception desk.", "Emailing full progress notes without encryption when convenient."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality includes physical and electronic safeguards: private session spaces, protected conversations, and secure record handling."}, {"id": "q257", "text": "A client posts a negative online review naming the counselor. What is the most ethical response?", "options": ["Reply publicly with details of the client's diagnosis to correct the record.", "Avoid confirming the person was a client and address reputation through appropriate professional channels without disclosing PHI.", "Post the client's session notes online.", "Sue immediately without consulting ethics or legal guidance."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Public responses can confirm a counseling relationship and breach confidentiality. Counselors should not disclose protected information when managing online reviews."}, {"id": "q258", "text": "When is it generally ethical for a counselor to break confidentiality without client consent?", "options": ["Whenever a family member asks for an update.", "When legally mandated or when there is serious, foreseeable, imminent risk requiring protective action, consistent with law and ethics.", "Whenever the counselor feels frustrated with the client.", "To impress a colleague with an interesting case."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Confidentiality exceptions typically include mandated reporting, duty to protect, and other legally required disclosures; voluntary gossip or convenience is not an exception."}, {"id": "q259", "text": "A counselor receives a large cash gift from a current client mid-treatment. What should the counselor do first?", "options": ["Accept silently to avoid awkwardness.", "Explore meaning, cultural context, clinical impact, and policy; generally decline gifts that may impair objectivity or create exploitation concerns.", "Accept and raise the fee next week.", "Ask the client for more gifts."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Gift decisions require clinical and cultural judgment. Large or mid-treatment gifts often raise boundary and exploitation concerns and should be carefully evaluated, usually declined, and documented."}, {"id": "q260", "text": "Which statement best describes counselor competence?", "options": ["Licensure permanently guarantees competence in every specialty.", "Competence is maintained through education, training, supervised experience, consultation, and practice within scope.", "Watching one webinar qualifies a counselor for all trauma treatments.", "Competence is irrelevant if the client likes the counselor."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical competence requires appropriate preparation and ongoing development, and practice within the boundaries of one's training and ability."}, {"id": "q261", "text": "A supervisee asks a supervisor to co-sign notes for sessions the supervisor did not review. The ethical supervisor should:", "options": ["Sign anything to save time.", "Only document and co-sign work that was actually supervised/reviewed according to standards and law.", "Allow the supervisee to forge signatures.", "Avoid supervision documentation entirely."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Supervisors are responsible for accurate documentation and should not misrepresent the nature or extent of supervision provided."}, {"id": "q262", "text": "Which action is most consistent with ethical termination?", "options": ["Ending abruptly without notice when the counselor is bored.", "Planning termination collaboratively when goals are met or services are no longer appropriate, with referrals and adequate notice when possible.", "Abandoning a client in crisis without resources.", "Continuing forever even when treatment is no longer beneficial."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical termination is planned when possible, avoids abandonment, addresses unfinished business, and provides referrals or continuity of care as needed."}, {"id": "q263", "text": "A counselor wants to use client stories in a public workshop. What is required?", "options": ["Nothing, because teaching justifies any disclosure.", "Adequate disguise of identity or valid authorization, and attention to whether disclosure could still harm the client.", "Using real names to make stories more authentic.", "Only changing the client's hair color in the story."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Case material used for teaching or writing must protect identity through thorough disguise or authorization, with ongoing attention to residual risk of recognition and harm."}, {"id": "q264", "text": "Which billing practice is unethical?", "options": ["Documenting sessions accurately and billing only for services rendered.", "Upcoding sessions or billing for missed sessions as if they occurred without a disclosed policy.", "Providing a clear fee agreement at intake.", "Sliding scale applied consistently per policy."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Fraudulent or deceptive billing, including representing services that did not occur or miscoding, violates ethical and legal standards."}, {"id": "q265", "text": "A client requests that the counselor withhold a serious suicide plan from the treatment team. The counselor should:", "options": ["Agree completely to maintain absolute secrecy.", "Explain limits of confidentiality related to safety and take appropriate protective action consistent with ethics, law, and agency policy.", "Ignore the plan because the client asked for secrecy.", "Only document the plan after the client dies."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Safety overrides a client's request for secrecy about imminent serious risk; counselors must act protectively while remaining transparent about limits of confidentiality."}, {"id": "q266", "text": "What is the best rationale for informed consent being an ongoing process?", "options": ["Clients never read forms once.", "Treatment goals, risks, roles, and circumstances can change, so clients need updated information to make autonomous decisions.", "It is only needed for research participants.", "Insurance companies forbid discussion after session one."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Informed consent is continuous because the counseling relationship and relevant information evolve over time."}, {"id": "q267", "text": "A counselor is subpoenaed to testify and has not received a release or court order compelling disclosure. What is the best initial stance?", "options": ["Reveal everything immediately in open court without review.", "Assert privilege/confidentiality as appropriate, seek legal consultation, and disclose only what is authorized or legally required.", "Destroy the record.", "Call the client's employer with details."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Counselors protect confidentiality to the extent allowed by law, consult legally, and release only authorized or court-compelled information."}, {"id": "q268", "text": "Which dual relationship is generally most problematic?", "options": ["Membership in a large professional association that a client also joined.", "Counseling a current employee whom the counselor supervises at work.", "Seeing a client at a grocery store and offering a brief polite greeting.", "Attending the same citywide concert as a client without interaction."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Concurrent hierarchical relationships (e.g., supervisor-employee plus counselor-client) create high risk of exploitation, impaired judgment, and role conflict."}, {"id": "q269", "text": "Ethical use of technology for client records most clearly requires:", "options": ["Password protection, access controls, encryption where appropriate, and compliance with applicable privacy laws.", "Storing records on any public shared drive labeled 'misc.'", "Never backing up data.", "Sharing login credentials with all staff for convenience."], "correct": 0, "domain": "Professional Practice and Ethics", "explanation": "Electronic records require reasonable administrative, technical, and physical safeguards consistent with professional and legal privacy standards."}, {"id": "q270", "text": "A counselor feels attracted to a current client. The most ethical first step is to:", "options": ["Disclose the attraction and pursue a relationship.", "Seek supervision/consultation, maintain boundaries, and consider transfer if objectivity is impaired.", "Increase session frequency to spend more time together.", "Ignore ethics codes because feelings are natural."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Attraction to clients requires professional management through consultation and boundaries; sexual/romantic involvement with current clients is prohibited."}, {"id": "q271", "text": "Which practice best reflects ethical cultural sensitivity in assessment interpretation?", "options": ["Applying majority-culture norms without question to all clients.", "Considering language, acculturation, test bias, and ecological validity when interpreting results.", "Assuming culture never affects test performance.", "Using only projective tests for bilingual clients."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical assessment requires culturally informed interpretation, including awareness of bias, language, and contextual factors affecting scores."}, {"id": "q272", "text": "What does a validity scale on a personality inventory primarily help the counselor evaluate?", "options": ["Whether the client's response style (e.g., overreporting, underreporting, inconsistency) may distort results.", "The client's exact IQ.", "Whether the counselor likes the client.", "The insurance reimbursement rate."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Validity scales assess response styles and protocol credibility, informing how cautiously clinical scales should be interpreted."}, {"id": "q273", "text": "A z-score of +1.0 approximately corresponds to which percentile in a normal distribution?", "options": ["16th percentile.", "50th percentile.", "84th percentile.", "99th percentile."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "In a normal distribution, about 84% of scores fall at or below one standard deviation above the mean."}, {"id": "q274", "text": "Which reliability type is most relevant when evaluating consistency of ratings between two independent observers?", "options": ["Test-retest reliability.", "Interrater reliability.", "Internal consistency only.", "Face validity."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Interrater reliability examines agreement between different raters or observers scoring the same phenomenon."}, {"id": "q275", "text": "Standard error of measurement (SEM) is most useful for:", "options": ["Estimating the range in which a client's true score is likely to fall.", "Proving a test is unbiased.", "Determining whether a construct is unidimensional by name alone.", "Calculating family income."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "SEM quantifies score imprecision and supports confidence bands around obtained scores."}, {"id": "q276", "text": "A client meets symptom criteria for a disorder but shows no clinically significant distress or impairment. What is the diagnostic implication?", "options": ["Diagnosis is automatically confirmed.", "Many diagnoses require clinically significant distress or impairment; absence may argue against the diagnosis.", "Impairment is never relevant in DSM diagnosis.", "The counselor should invent impairment to justify billing."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Most mental disorder diagnoses require clinically significant distress or functional impairment, not symptoms alone."}, {"id": "q277", "text": "Which assessment approach is most appropriate at first contact with a highly distressed client?", "options": ["A full 6-hour battery before any rapport.", "Brief risk and needs screening, alliance building, and prioritized clinical assessment.", "No assessment until month three.", "Only projective drawings without interview."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Initial contacts prioritize safety, engagement, and essential clinical information rather than exhaustive testing that may overwhelm the client."}, {"id": "q278", "text": "Construct validity is best described as:", "options": ["Whether a test looks reasonable to examinees.", "The degree to which a test measures the theoretical construct it purports to measure.", "Whether two halves of a test correlate.", "Whether scores stay the same over 20 years."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Construct validity concerns theoretical meaning of scores and evidence that the instrument measures the intended construct."}, {"id": "q279", "text": "A mental status exam finding of 'tangential thought process' means the client:", "options": ["Answers briefly and stays on topic.", "Digresses from the topic and does not return to the original point.", "Has perfect concentration.", "Always speaks in rhymes."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Tangentiality involves departing from the topic without returning; it is a thought-process observation on the MSE."}, {"id": "q280", "text": "Which information is most critical when assessing for substance use disorder severity?", "options": ["Favorite beverage brand only.", "Pattern of use, loss of control, tolerance/withdrawal, consequences, and impairment across life domains.", "Whether friends drink more.", "Only whether use is legal."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "SUD assessment examines control, physiological features, risk/consequences, and functional impairment—not legality alone."}, {"id": "q281", "text": "A counselor uses a cutoff score from a screening tool. What is a key limitation to communicate?", "options": ["Screeners are definitive diagnoses.", "Screening tools can yield false positives/negatives and require clinical follow-up for diagnosis.", "Cutoff scores never err.", "Screeners replace clinical interviews entirely."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Screening instruments flag risk or possible problems but are not substitutes for comprehensive diagnostic evaluation."}, {"id": "q282", "text": "Which client presentation most warrants immediate medical referral alongside counseling assessment?", "options": ["Mild situational worry before an exam.", "Sudden severe headache, confusion, and neurological changes with anxiety-like symptoms.", "Preference for morning sessions.", "Mild frustration with traffic."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Acute medical/neurological red flags require prompt medical evaluation; psychological symptoms can mask medical emergencies."}, {"id": "q283", "text": "In classical test theory, observed score equals:", "options": ["True score plus error.", "Only true score with no error.", "Error minus true score.", "The mean of the population always."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Classical test theory models an observed score as the sum of true score and measurement error."}, {"id": "q284", "text": "Which question best assesses protective factors during suicide risk assessment?", "options": ["What reasons do you have for living, and who or what helps you stay safe?", "How quickly can you access means?", "When did you first feel sad?", "What is your favorite color?"], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Protective factors (reasons for living, supports, coping, future orientation) are essential alongside risk factors in a complete suicide assessment."}, {"id": "q285", "text": "A client reports 'voices' that are actually their own critical thoughts recognized as internal. This is most consistent with:", "options": ["True auditory hallucination with loss of reality testing.", "An internal experience that should be carefully differentiated from psychotic hallucinations.", "Automatic proof of schizophrenia.", "Malingering only."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Clinicians must distinguish true hallucinations from intrusive thoughts, pseudohallucinations, or metaphorical language before diagnosing psychosis."}, {"id": "q286", "text": "Norm-referenced interpretation compares a client's score to:", "options": ["An absolute mastery standard only.", "The performance of a defined norm group.", "The counselor's personal opinion alone.", "Random numbers."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Norm-referenced scores locate performance relative to a comparison group, unlike criterion-referenced mastery standards."}, {"id": "q287", "text": "Which practice improves the cultural validity of a clinical interview?", "options": ["Using only closed yes/no questions and medical jargon.", "Exploring explanatory models, language preference, supports, and stressors in cultural context.", "Assuming symptoms mean the same thing in every culture.", "Avoiding any discussion of identity."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Culturally responsive interviewing elicits the client's meaning-making, context, language needs, and culturally relevant stressors and strengths."}, {"id": "q288", "text": "Comorbidity in diagnosis means:", "options": ["The client has no diagnosis.", "Two or more disorders are present in the same person.", "The client is noncompliant.", "Testing was invalid."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Comorbidity refers to co-occurrence of multiple disorders, which affects assessment, prognosis, and treatment planning."}, {"id": "q289", "text": "Which is the best example of a process goal versus an outcome goal?", "options": ["Outcome: reduce PHQ-9 by 50%; Process: attend weekly sessions and complete thought records twice weekly.", "Process and outcome goals are identical.", "Process: cure depression forever; Outcome: buy a workbook.", "Outcome goals should never be measurable."], "correct": 0, "domain": "Treatment Planning", "explanation": "Outcome goals target clinical results; process goals specify engagement and therapeutic activities that support those results."}, {"id": "q290", "text": "A client's insurance authorizes six sessions. How should this influence treatment planning?", "options": ["Ignore authorization and never discuss limits.", "Prioritize high-impact goals, discuss constraints transparently, and plan for continuity or referral as needed.", "Provide no treatment because six sessions are useless.", "Guarantee full resolution of lifelong trauma in six sessions."], "correct": 1, "domain": "Treatment Planning", "explanation": "Ethical brief planning prioritizes feasible goals, informed consent about limits, and aftercare or referral options."}, {"id": "q291", "text": "What is the main advantage of using standardized outcome measures in treatment planning?", "options": ["They replace the need for a relationship.", "They provide baseline and progress data to guide collaborative adjustments.", "They eliminate cultural considerations.", "They always diagnose accurately alone."], "correct": 1, "domain": "Treatment Planning", "explanation": "Routine outcome monitoring informs whether interventions are working and when to revise the plan."}, {"id": "q292", "text": "Which treatment plan element best addresses barriers to care?", "options": ["Ignoring childcare and transportation issues.", "Identifying obstacles (schedule, cost, stigma, access) and building strategies to reduce them.", "Assuming motivation alone solves all barriers.", "Blaming the client for systemic barriers only."], "correct": 1, "domain": "Treatment Planning", "explanation": "Effective plans anticipate practical and psychosocial barriers and include strategies to support engagement."}, {"id": "q293", "text": "In crisis-oriented treatment planning, the first-order goals typically focus on:", "options": ["Personality reorganization.", "Safety, stabilization, and reduction of acute distress.", "Career interest inventories only.", "Long-term existential exploration exclusively."], "correct": 1, "domain": "Treatment Planning", "explanation": "Crisis plans emphasize immediate safety and stabilization before longer-term developmental or insight goals."}, {"id": "q294", "text": "A client's goal seems unrealistic within the timeframe. The best approach is to:", "options": ["Silently accept and set the client up for failure.", "Collaboratively refine goals into meaningful, achievable steps while honoring the client's values.", "Mock the client's ambition.", "Refuse all goal discussion."], "correct": 1, "domain": "Treatment Planning", "explanation": "Collaborative planning balances hope with feasibility by shaping goals into attainable steps without dismissing client aspirations."}, {"id": "q295", "text": "Which statement best describes an evidence-informed treatment plan?", "options": ["It ignores research and relies only on intuition.", "It integrates research-supported interventions with client preferences, culture, and clinical expertise.", "It uses only the newest untested technique.", "It copies a generic plan for every diagnosis without individualization."], "correct": 1, "domain": "Treatment Planning", "explanation": "Evidence-based practice combines best research evidence, clinician expertise, and client characteristics and preferences."}, {"id": "q296", "text": "Including family members in a minor's treatment plan is most appropriate when:", "options": ["It is never appropriate.", "Clinically indicated, legally allowed, and aligned with consent/assent and the minor's best interests.", "The counselor wants free translators.", "The minor forbids any caregiver involvement in all cases regardless of age and law."], "correct": 1, "domain": "Treatment Planning", "explanation": "Family involvement is planned according to clinical need, developmental status, consent rules, and welfare of the minor."}, {"id": "q297", "text": "What is a discharge criterion in a treatment plan?", "options": ["A vague hope that things improve.", "Predefined indicators that goals are met or services should step down or end.", "The counselor's vacation date only.", "When the client becomes mildly annoyed."], "correct": 1, "domain": "Treatment Planning", "explanation": "Discharge criteria specify when treatment can appropriately conclude or transition based on goal attainment and clinical status."}, {"id": "q298", "text": "A client with panic disorder and diabetes needs coordinated care. The plan should include:", "options": ["Isolation from all medical providers.", "Appropriate releases and collaboration with medical providers when relevant to holistic care.", "Counselor-prescribed medication changes without training.", "Ignoring physical health entirely."], "correct": 1, "domain": "Treatment Planning", "explanation": "Integrated planning coordinates mental and physical health care with proper authorization and role boundaries."}, {"id": "q299", "text": "Which goal best fits a client in precontemplation for smoking cessation?", "options": ["Quit permanently tomorrow without discussion.", "Increase awareness of personal impact and explore ambivalence without forcing action.", "Punish the client for smoking.", "Refuse to discuss smoking at all."], "correct": 1, "domain": "Treatment Planning", "explanation": "Precontemplation work focuses on engagement and awareness rather than premature action goals the client is not ready to pursue."}, {"id": "q300", "text": "Progress notes should relate to the treatment plan by:", "options": ["Ignoring goals and writing only social chat.", "Documenting interventions used and client response relative to planned goals/objectives.", "Copying the same note daily without change.", "Recording only billing codes with no clinical content."], "correct": 1, "domain": "Treatment Planning", "explanation": "Notes should connect session work to the plan, showing what was done and how the client responded toward goals."}, {"id": "q301", "text": "When two goals conflict (e.g., autonomy vs. safety), the counselor should:", "options": ["Always choose the easier paperwork option.", "Prioritize safety when risk is significant, while maximizing client autonomy to the extent safely possible and documenting rationale.", "Ignore both goals.", "Let social media followers decide."], "correct": 1, "domain": "Treatment Planning", "explanation": "Ethical prioritization places safety first under significant risk while preserving autonomy as much as is clinically and ethically feasible."}, {"id": "q302", "text": "A strength-based treatment plan would most likely include:", "options": ["Only deficits and pathology lists.", "Client strengths, resources, and protective factors as active supports for change.", "No mention of culture or supports.", "Goals written solely in problem language."], "correct": 1, "domain": "Treatment Planning", "explanation": "Strength-based planning mobilizes client and environmental resources rather than focusing exclusively on deficits."}, {"id": "q303", "text": "Which is the best reason to revise a treatment plan mid-care?", "options": ["The counselor is bored with the current plan.", "New assessment data, stalled progress, changed goals, or emerging risk require adjustment.", "A friend suggested a random technique.", "The plan is only two weeks old, so revision is forbidden."], "correct": 1, "domain": "Treatment Planning", "explanation": "Plans should change when clinical reality changes—new information, insufficient progress, goal shifts, or risk developments."}, {"id": "q304", "text": "In group counseling treatment planning, individual goals should be:", "options": ["Identical for every member regardless of needs.", "Linked to group purpose while remaining relevant to each member's presenting concerns.", "Secret from the leader.", "Focused only on leader self-disclosure."], "correct": 1, "domain": "Treatment Planning", "explanation": "Effective group work aligns personal goals with the group's purpose and therapeutic factors available in the group modality."}, {"id": "q305", "text": "Minimal encouragers (e.g., 'mm-hmm,' 'go on') are primarily used to:", "options": ["Interrupt and redirect constantly.", "Support client continuation and convey attending without taking the floor.", "Diagnose personality disorders.", "End sessions abruptly."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Minimal encouragers are attending skills that invite the client to continue speaking."}, {"id": "q306", "text": "A reflection of meaning differs from a reflection of feeling because it:", "options": ["Ignores the client entirely.", "Captures the significance, values, or worldview underlying the client's narrative, not only the emotion.", "Is only used in career counseling.", "Must include advice."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Reflections of meaning address deeper significance and values; feeling reflections target affect."}, {"id": "q307", "text": "Immediacy in counseling refers to:", "options": ["Talking only about childhood.", "Addressing the here-and-now relationship or what is occurring between counselor and client in the moment.", "Sending texts between sessions about weather.", "Avoiding all process comments."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Immediacy brings present-tense relational process into the therapeutic dialogue when clinically useful."}, {"id": "q308", "text": "Which intervention is most consistent with behavioral activation for depression?", "options": ["Increasing engagement in valued, reinforcing activities despite low motivation.", "Only free association for months.", "Avoiding all activity until mood improves spontaneously.", "Challenging only existential meaning with no behavioral focus."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral activation targets avoidance and withdrawal by scheduling and engaging in reinforcing, valued activities."}, {"id": "q309", "text": "Systematic desensitization classically pairs:", "options": ["Punishment with every anxiety cue.", "Gradual exposure hierarchy items with relaxation or competing responses.", "Only flooding from session one for all clients.", "Career card sorts with Rorschach cards."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Systematic desensitization combines hierarchical exposure with relaxation or counterconditioning principles."}, {"id": "q310", "text": "In person-centered counseling, the counselor's primary 'technique' emphasis is on:", "options": ["Directive homework every session as the core method.", "Facilitative conditions—empathy, congruence, and unconditional positive regard—within the relationship.", "Dream interpretation manuals.", "Token economies exclusively."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Person-centered practice centers the therapeutic conditions of the relationship rather than a large toolkit of directive techniques."}, {"id": "q311", "text": "A scaling question (0–10) in solution-focused work is mainly used to:", "options": ["Assign a formal DSM code.", "Assess current status, exceptions, and small steps toward a preferred future.", "Measure blood pressure.", "Replace all other counseling skills forever."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Scaling helps clients quantify progress, identify partial successes, and define next small improvements."}, {"id": "q312", "text": "Which response is an open question?", "options": ["Did you go to work today?", "What was going through your mind when the argument started?", "Are you sad?", "Is your boss mean?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Open questions invite elaboration; closed questions typically elicit yes/no or brief factual answers."}, {"id": "q313", "text": "Confrontation as a counseling skill is best defined as:", "options": ["Yelling at the client.", "Gently pointing out discrepancies among feelings, behaviors, and statements to promote awareness.", "Threatening to terminate for minor lateness.", "Arguing to win."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic confrontation highlights inconsistencies in a respectful way to facilitate insight and change, not aggression."}, {"id": "q314", "text": "In MI, 'sustain talk' refers to:", "options": ["Client language favoring the status quo and against change.", "Only counselor lectures.", "Group icebreakers.", "Career values card sort results."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Sustain talk expresses reasons to stay the same; change talk expresses movement toward change. MI seeks to evoke change talk."}, {"id": "q315", "text": "Which group leadership function is most important in the initial stage?", "options": ["Pushing deep interpersonal confrontation immediately for all members.", "Establishing norms, safety, purpose, and facilitating inclusion and trust-building.", "Remaining completely silent for all sessions.", "Focusing only on leader self-disclosure."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Early group work emphasizes orientation, norms, cohesion beginnings, and psychological safety."}, {"id": "q316", "text": "Reframing helps clients by:", "options": ["Denying their experience.", "Offering an alternative, more workable perspective on a situation or behavior.", "Replacing all client words with jargon.", "Avoiding emotional content permanently."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Reframes shift meaning in ways that can reduce stuckness and open new behavioral options while still respecting client experience."}, {"id": "q317", "text": "Which technique is most associated with narrative therapy?", "options": ["Externalizing the problem and exploring unique outcomes that contradict the dominant problem story.", "Flooding hierarchies only.", "Free association to uncover Oedipal conflicts exclusively.", "Biofeedback without conversation."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Narrative approaches separate person from problem (externalization) and thicken preferred stories through unique outcomes."}, {"id": "q318", "text": "Self-disclosure by the counselor is most appropriate when it:", "options": ["Meets the counselor's needs for support.", "Is brief, relevant, and likely to benefit the client's therapeutic process.", "Shares intimate details every session.", "Compares the client unfavorably to the counselor's life."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Therapeutic self-disclosure is client-centered, purposeful, and limited—not a vehicle for counselor unmet needs."}, {"id": "q319", "text": "In exposure therapy for specific phobia, safety behaviors are often targeted because they:", "options": ["Always increase long-term learning of safety.", "Can prevent disconfirmation of feared outcomes and maintain anxiety.", "Are identical to values-based living.", "Replace the need for any hierarchy."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Safety behaviors may block corrective learning during exposure; reducing them carefully can improve treatment effects."}, {"id": "q320", "text": "Summarization is especially useful at:", "options": ["Only the first minute of intake.", "Transition points, session openings/closings, and when organizing complex client material.", "Times when the counselor wants to dominate.", "Moments requiring medical prescription."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Summaries organize content and affect, check understanding, and help structure session flow and focus."}, {"id": "q321", "text": "Which intervention best fits dialectical behavior therapy (DBT) skills training?", "options": ["Teaching mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness skills.", "Only empty-chair work for unfinished business.", "Only career genograms.", "Only free association."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "DBT skills modules classically include mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness."}, {"id": "q322", "text": "According to Holland, a person high in Investigative interests is most likely to enjoy:", "options": ["Persuading others in sales roles primarily.", "Scientific, analytic, and research-oriented activities.", "Only unstructured artistic chaos with no inquiry.", "Routine clerical filing exclusively."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Investigative types prefer analytical, scientific, and intellectual problem-solving environments and tasks."}, {"id": "q323", "text": "Krumboltz's social learning theory of career decision making emphasizes:", "options": ["Genetic luck only.", "Learning experiences, environmental conditions, task approach skills, and cognitive processes influencing career paths.", "That careers are fixed at birth.", "Ignoring chance events."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Krumboltz highlights learning experiences and cognitive-behavioral factors, including the role of planned happenstance/chance."}, {"id": "q324", "text": "The stages of change (transtheoretical model) progress most accurately as:", "options": ["Action, then precontemplation, then maintenance only.", "Precontemplation, contemplation, preparation, action, maintenance (with possible relapse/recycling).", "Only action and termination.", "Denial, anger, bargaining as career stages."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "TTM stages include precontemplation through maintenance, recognizing non-linear movement and relapse as common."}, {"id": "q325", "text": "A client with PTSD avoids trauma reminders and reports hyperarousal. A first-line counseling consideration is:", "options": ["Forced detailed exposure in minute one without preparation for every client.", "Safety, stabilization, psychoeducation, and evidence-based trauma treatment matched to readiness and training.", "Ignoring avoidance because it is adaptive long-term in all cases.", "Only career counseling."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Trauma work prioritizes safety and appropriate pacing; evidence-based treatments require competence and client readiness."}, {"id": "q326", "text": "Piaget's stage characterized by abstract reasoning and hypothetical thinking is:", "options": ["Sensorimotor.", "Preoperational.", "Concrete operational.", "Formal operational."], "correct": 3, "domain": "Areas of Clinical Focus", "explanation": "Formal operations involve abstract, hypothetical-deductive reasoning typically emerging in adolescence."}, {"id": "q327", "text": "Bowlby's attachment theory most strongly emphasizes:", "options": ["Random peer groups only in adulthood.", "Early caregiver bonds shaping internal working models of self and others.", "That attachment is irrelevant after age two.", "Only cognitive schemas about math."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Attachment theory posits that early relational bonds form internal working models influencing later relationships and emotion regulation."}, {"id": "q328", "text": "A client reports microaggressions at work and resulting anxiety. Culturally responsive counseling would:", "options": ["Deny that microaggressions exist.", "Validate the experience, explore impact and coping, and consider advocacy/empowerment options as appropriate.", "Tell the client to toughen up only.", "Change the topic to hobbies permanently."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Affirming clients' experiences of discrimination and addressing psychological impact are core to multicultural counseling practice."}, {"id": "q329", "text": "Which family therapy approach is most associated with hierarchical structure, subsystems, and boundaries?", "options": ["Structural family therapy (Minuchin).", "Classical psychoanalysis of only one parent.", "Person-centered individual therapy exclusively.", "REBT worksheets without family process."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Minuchin's structural model focuses on family organization, subsystems, boundaries, and hierarchical clarity."}, {"id": "q330", "text": "Bowen family systems theory especially emphasizes:", "options": ["Differentiation of self, triangles, and multigenerational patterns.", "Only token economies for children.", "Flooding for phobias as the family cure.", "Ignoring family history."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Bowen concepts include differentiation, triangulation, emotional cutoff, and multigenerational transmission."}, {"id": "q331", "text": "An older adult client presents with sudden cognitive decline and depression. What is an important clinical focus?", "options": ["Assume symptoms are 'just aging' without evaluation.", "Assess for medical contributions, depression vs. neurocognitive concerns, supports, and appropriate referrals.", "Only childhood free association.", "Mandatory retirement counseling only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Late-life changes require careful differential assessment, medical collaboration, and attention to functioning and supports."}, {"id": "q332", "text": "Which issue is most central in counseling clients with chronic illness?", "options": ["Ignoring grief and identity changes.", "Coping, adjustment, meaning, adherence barriers, and mental health comorbidity related to illness course.", "Assuming illness has no psychological impact.", "Only IQ testing."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Chronic illness counseling addresses adjustment, mood/anxiety, identity, relationships, and practical coping across the illness trajectory."}, {"id": "q333", "text": "A college student presents with perfectionism, all-or-nothing thinking, and binge-purge behaviors. Priority clinical focus includes:", "options": ["Medical stability assessment and eating-disorder-informed care with appropriate referrals.", "Only increasing study hours.", "Ignoring physical risk.", "Assuming it is only a willpower problem."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Eating disorder presentations require attention to medical risk, specialized treatment, and coordinated care—not minimization."}, {"id": "q334", "text": "Gottman's research on couples most famously identifies which pattern as highly destructive?", "options": ["Shared humor.", "The 'Four Horsemen' (criticism, contempt, defensiveness, stonewalling).", "Expressing fondness.", "Softened startup."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Gottman highlighted criticism, contempt, defensiveness, and stonewalling as particularly corrosive interaction patterns."}, {"id": "q335", "text": "Which career assessment is most associated with measuring interests rather than aptitudes?", "options": ["A values card sort or RIASEC interest inventory.", "A pure reaction-time motor test only.", "Bloodwork panels.", "A hearing screening."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Interest inventories and values tools assess preferences and motivations; aptitude tests estimate abilities."}, {"id": "q336", "text": "A client in acute mania with poor sleep and reckless spending is brought by family. Counseling priority is:", "options": ["Long psychoanalytic interpretation first.", "Safety, medical/psychiatric evaluation for level of care, and stabilization before insight-oriented work.", "Career interest testing immediately.", "Ignoring risk because the client feels 'great.'"], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Acute mania often requires medical/psychiatric stabilization and risk management before deeper psychosocial work."}, {"id": "q337", "text": "Acculturative stress is best described as:", "options": ["Stress arising from adapting to a new cultural environment and navigating cultural conflicts.", "Only genetic anxiety.", "A formal psychotic disorder.", "Unrelated to immigration or cultural transition."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Acculturative stress involves psychological strain from cultural adaptation, discrimination, language, and identity conflicts."}, {"id": "q338", "text": "Which factor is most important when counseling LGBTQ+ clients according to affirmative practice?", "options": ["Attempting conversion of identity.", "Affirming identity, understanding minority stress, and creating a safe, nonpathologizing therapeutic environment.", "Avoiding any discussion of relationships.", "Assuming all distress is caused only by identity."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Affirmative practice supports identity, addresses minority stress and discrimination, and rejects pathologizing or conversion approaches."}, {"id": "q339", "text": "Warmth in counseling is best demonstrated by:", "options": ["Emotional coldness framed as professionalism.", "Friendly, accepting nonverbal and verbal behavior that helps clients feel valued without boundary loss.", "Hugging every client regardless of preference.", "Sharing all personal secrets."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic warmth conveys acceptance and care while maintaining professional boundaries and client comfort."}, {"id": "q340", "text": "Which attribute most helps a counselor sit with ambiguity in complex cases?", "options": ["Tolerance for uncertainty paired with careful assessment and consultation.", "Premature closure on a single explanation always.", "Certainty without data.", "Avoidance of the case."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Clinical work often involves incomplete data; effective counselors tolerate ambiguity while continuing disciplined inquiry."}, {"id": "q341", "text": "Integrity as a counselor attribute primarily means:", "options": ["Acting consistently with ethical principles even when inconvenient.", "Keeping every client happy at any ethical cost.", "Hiding mistakes from supervisors.", "Promising outcomes you cannot deliver."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Integrity involves honesty, ethical consistency, and alignment between professional values and behavior."}, {"id": "q342", "text": "A counselor who regularly seeks feedback on their work is demonstrating:", "options": ["Weakness.", "Reflective practice and commitment to growth.", "Boundary violation.", "Lack of knowledge only."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Inviting feedback supports reflective practice, skill development, and higher-quality care."}, {"id": "q343", "text": "Compassion fatigue risk is reduced most by:", "options": ["Ignoring personal needs indefinitely.", "Sustainable caseloads, supervision, self-care, and organizational supports.", "Taking on every crisis without limits.", "Isolating from colleagues."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Preventing compassion fatigue requires systemic and personal strategies that protect counselor functioning and client care."}, {"id": "q344", "text": "Nonjudgmental acceptance means the counselor:", "options": ["Agrees with all client behaviors.", "Respects the client's worth even while addressing harmful behaviors and consequences.", "Never discusses values or change.", "Avoids any limit-setting."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Acceptance of the person coexists with ethical responsibility to address harm, risk, and behavior change collaboratively."}, {"id": "q345", "text": "Which quality is most essential when a client challenges the counselor's cultural assumptions?", "options": ["Defensiveness and debate to win.", "Openness, humility, and willingness to repair and learn.", "Immediate termination for disrespect.", "Changing the subject permanently."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Cultural humility includes receiving client feedback nondefensively and adjusting practice."}, {"id": "q346", "text": "Professional presence includes:", "options": ["Being chronically late and distracted.", "Reliability, preparedness, and respectful engagement that communicates the client matters.", "Multitasking emails during sessions.", "Canceling frequently without notice."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Presence and professionalism are shown through reliability, attention, and respectful engagement."}, {"id": "q347", "text": "A counselor feels hopeless about a chronic client's progress. The healthiest attribute-driven response is to:", "options": ["Convey hopelessness as a diagnosis to the client.", "Use supervision to process reactions, reassess the plan, and sustain a realistic hopeful stance.", "Terminate without discussion.", "Blame the client publicly."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Counselors manage their own reactions professionally, seek consultation, and maintain a balanced therapeutic stance."}, {"id": "q348", "text": "Authenticity without ethics is problematic because:", "options": ["Authenticity is never useful.", "Unfiltered self-expression can harm clients; genuineness must remain boundaried and client-centered.", "Ethics forbid any real human connection.", "Clients only want techniques, never relationship."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic genuineness is not license for harmful disclosure; it is authenticity within professional role and ethics."}, {"id": "q349", "text": "Patience as a counseling attribute is most evident when the counselor:", "options": ["Rushes clients to the counselor's preferred timeline.", "Allows clients to move at a clinically appropriate pace while still addressing safety and goals.", "Avoids all structure.", "Ignores risk indefinitely."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Patience supports client pacing and readiness without abandoning structure, goals, or safety responsibilities."}, {"id": "q350", "text": "Which attribute best supports working with clients who hold values different from the counselor's?", "options": ["Value imposition.", "Respect for autonomy and bracketing personal values that would interfere with client welfare.", "Debating clients until they convert.", "Refusing all value-laden topics always."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Ethical practice respects client autonomy and avoids imposing the counselor's personal values on client goals."}, {"id": "q351", "text": "Courage in counseling may look like:", "options": ["Avoiding all difficult topics.", "Addressing risk, rupture, or hard truths compassionately when it serves the client.", "Being harsh to appear strong.", "Taking reckless dual relationship risks."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic courage involves entering difficult but necessary conversations with care and skill."}, {"id": "q352", "text": "A counselor who notices preferential treatment toward clients similar to themselves is demonstrating a need for:", "options": ["More bias without reflection.", "Self-awareness and corrective action regarding countertransference and equity.", "Keeping the preference secret forever.", "Only seeing similar clients."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Awareness of bias and preferential pulls is essential to fair, ethical, and effective care for all clients."}, {"id": "q353", "text": "Hope as a counselor attribute is best described as:", "options": ["Toxic positivity that denies real barriers.", "A realistic belief that change is possible, paired with honest appraisal of challenges.", "Guaranteeing specific outcomes.", "Avoiding discussion of setbacks."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Therapeutic hope is grounded and honest—supporting possibility without denying difficulty or promising impossible results."}, {"id": "q354", "text": "Which combination best captures mature professional empathy?", "options": ["Feeling with the client while maintaining differentiation and the capacity to think clinically.", "Merging completely with client emotion and losing role.", "Intellectual analysis with no emotional attunement.", "Pity that elevates the counselor above the client."], "correct": 0, "domain": "Core Counseling Attributes", "explanation": "Mature empathy joins affective attunement with professional boundaries and clinical thinking rather than fusion or cold detachment."}, {"id": "q355", "text": "A counselor discovers an unpaid client balance after termination. The most ethical first step is to:", "options": ["Harass the client on social media until paid.", "Follow the fee agreement and ethical collection practices, avoiding harmful or confidential disclosures.", "Publish the client's diagnosis publicly.", "Refuse all future referrals from that city."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Fee recovery must respect dignity, confidentiality, and the original fee agreement; coercive or public shaming tactics are unethical."}, {"id": "q356", "text": "Which situation most clearly constitutes client abandonment?", "options": ["Collaborative termination with referrals when goals are met.", "Ending services abruptly without adequate notice or referral while the client still needs care, especially in crisis.", "Transferring a client with a warm handoff.", "Taking a planned vacation with coverage arranged."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Abandonment involves discontinuing needed services without appropriate notice, planning, or referral."}, {"id": "q357", "text": "A counselor wants to accept a friend as a therapy client in a rural area with few providers. The best ethical approach is to:", "options": ["Accept automatically because rural practice has no rules.", "Carefully evaluate dual-relationship risks, alternatives, informed consent, and consultation before deciding; refer when risk is too high.", "Begin without documenting the dual relationship.", "Require the friend to keep the therapy secret from mutual acquaintances only."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Nonsexual dual relationships require case-by-case evaluation of benefit, risk, alternatives, consent, and documentation—especially in rural settings."}, {"id": "q358", "text": "Which statement about counselor values and client autonomy is most accurate?", "options": ["Counselors may impose personal values when they strongly disagree with clients.", "Counselors respect client autonomy and avoid imposing personal values, seeking consultation or referral when competence or harm is at issue.", "Client autonomy never applies to minor decisions.", "Values conflicts always require immediate termination."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Ethical practice honors client self-determination and forbids value imposition while addressing competence and welfare concerns appropriately."}, {"id": "q359", "text": "HIPAA-related counseling practice most directly concerns:", "options": ["Only office paint colors.", "Privacy, security, and permitted uses/disclosures of protected health information.", "Career interest matching exclusively.", "Guaranteeing cure rates."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "HIPAA sets national standards for protecting health information privacy and security for covered entities."}, {"id": "q360", "text": "A client who is a minor discloses ongoing physical abuse by a caregiver. The counselor should:", "options": ["Keep absolute secrecy if the minor asks.", "Follow mandated reporting laws and agency policy while attending to the minor's safety and support.", "Call the alleged abuser first to verify before any report.", "Wait until the next annual review."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Suspected child abuse typically requires mandated reporting; counselors act to protect the child within legal and ethical frameworks."}, {"id": "q361", "text": "Which practice is most appropriate when a counselor lacks competence in a needed specialty?", "options": ["Pretend competence to retain the client.", "Obtain training/supervision or make an appropriate referral so the client receives competent care.", "Use experimental methods without consent.", "Ask the client to teach the specialty."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Practice within competence; seek training, supervision, or referral rather than providing inadequate care."}, {"id": "q362", "text": "An ethical informed consent discussion for group counseling should include:", "options": ["Only the meeting time.", "Group purpose, format, risks/benefits, confidentiality limits among members, and expectations for participation.", "A promise that no member will ever break confidentiality.", "No discussion of fees."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Group consent covers process, risks, benefits, and the special confidentiality limits that arise with multiple members."}, {"id": "q363", "text": "A counselor is asked to evaluate a current therapy client for a court custody case. The best response is to:", "options": ["Serve as both therapist and forensic evaluator to be efficient.", "Avoid dual roles; decline forensic evaluation of a current client and explain role conflicts.", "Write whatever the client wants for court.", "Destroy clinical notes before testifying."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Therapeutic and forensic roles conflict; counselors avoid dual roles that impair objectivity and harm the therapeutic relationship."}, {"id": "q364", "text": "Which action best supports ethical advertising of counseling services?", "options": ["Guaranteeing specific outcomes and using fabricated testimonials.", "Providing accurate credentials, services, and claims without deceptive guarantees.", "Implying specialty certification not held.", "Comparing competitors with false statements."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Advertising must be truthful regarding qualifications, services, and expected outcomes without deception."}, {"id": "q365", "text": "When a client dies, ethical record handling generally includes:", "options": ["Posting the chart online as a memorial.", "Maintaining records securely per law/policy and releasing information only to authorized parties.", "Giving the full file to any relative who asks without verification.", "Immediately shredding all notes the same day without legal review."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Records remain protected after death; disclosure follows legal authority and professional standards."}, {"id": "q366", "text": "A counselor provides pro bono services. Ethically, the counselor should:", "options": ["Provide lower-quality care than for paying clients.", "Maintain the same professional standards of competence, consent, and documentation as with other clients.", "Skip progress notes because there is no fee.", "Ignore boundaries because services are free."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Pro bono work still requires full professional standards; reduced fees do not reduce ethical obligations."}, {"id": "q367", "text": "Which scenario most clearly requires consultation?", "options": ["A routine scheduling change.", "A complex ethical dilemma involving dual relationships, risk, or competence boundaries.", "Choosing office snacks.", "Updating a voicemail greeting."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Consultation is indicated for ethical complexity, risk, dual roles, and competence questions."}, {"id": "q368", "text": "A client asks the counselor to lie to an insurer about diagnosis to obtain coverage. The counselor should:", "options": ["Agree to help the client get benefits.", "Refuse fraudulent documentation and discuss ethical/legal alternatives and accurate advocacy options.", "Bill a more severe diagnosis secretly.", "Have the client forge the counselor's signature."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Fraudulent billing or diagnosis is unethical and illegal; counselors maintain honesty in records and claims."}, {"id": "q369", "text": "Distance counseling across state lines most critically requires attention to:", "options": ["Only the counselor's preferred software theme.", "Licensure/jurisdiction, emergency procedures, and technology-related informed consent.", "Whether the client likes the counselor's virtual background.", "Avoiding any discussion of location."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Telehealth practice must address jurisdiction/licensure, crisis response by location, and modality-specific consent."}, {"id": "q370", "text": "Which is the best example of a boundary crossing that may be ethical if carefully managed?", "options": ["A sexual relationship with a current client.", "Attending a client's graduation when clinically appropriate, with clear rationale, cultural sensitivity, and documentation.", "Borrowing large sums of money from a client.", "Becoming the client's employer and therapist simultaneously without review."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Some boundary crossings can be beneficial if intentional, non-exploitative, and well processed; sexual dual roles are not in this category."}, {"id": "q371", "text": "Ethical research with counseling clients requires:", "options": ["Using clients as subjects without telling them.", "Informed consent, minimization of harm, voluntary participation, and IRB/ethical oversight as applicable.", "Coercing clients by implying better care if they participate.", "Publishing identifiable case details for impact."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Research ethics require consent, voluntary participation, risk minimization, and appropriate review."}, {"id": "q372", "text": "A counselor's personal social media should ideally:", "options": ["Friend all current clients for transparency.", "Use privacy settings and professional policies that prevent harmful dual relationships and confidentiality breaches.", "Post client progress stories with first names.", "Argue with clients in comment sections."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Social media policies and privacy practices help maintain boundaries and protect client confidentiality."}, {"id": "q373", "text": "Which record-keeping practice is most ethical?", "options": ["Backdating notes weeks later without indication.", "Timely, accurate, and sufficiently thorough documentation of clinically relevant information.", "Including gossip from the waiting room.", "Never documenting risk assessments."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Records should be timely, accurate, relevant, and protective of privacy while supporting continuity of care."}, {"id": "q374", "text": "A supervisor asks a counselor to ignore a mandated report to protect agency reputation. The counselor should:", "options": ["Comply to keep the job.", "Follow legal/ethical reporting duties and seek appropriate consultation/advocacy channels.", "Falsify the chart to hide the concern.", "Tell the client to never return."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Legal and ethical duties to protect vulnerable persons supersede organizational pressure to suppress reports."}, {"id": "q375", "text": "Which best describes privileged communication?", "options": ["A counselor's right to gossip with friends.", "A legal protection limiting compelled disclosure of confidential counseling communications in legal proceedings, with exceptions.", "Unlimited secrecy even when a court order is valid.", "The same as etiquette only."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Privilege is a legal concept restricting courtroom disclosure of confidential communications, subject to exceptions and jurisdiction."}, {"id": "q376", "text": "When translating services are needed, ethical practice favors:", "options": ["Using a minor child as interpreter for trauma content.", "Qualified interpreters and attention to confidentiality, accuracy, and cultural nuance.", "Assuming the client understands complex English.", "Skipping consent because language is a barrier."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Qualified interpretation protects informed consent, accuracy, and confidentiality better than ad hoc family interpreters."}, {"id": "q377", "text": "A counselor receives a request for records from a third party without a release. The counselor should:", "options": ["Send everything immediately to be cooperative.", "Decline unauthorized disclosure and request proper authorization or legal compulsion as applicable.", "Read the notes aloud over the phone to anyone who calls.", "Mail records to an unverified address."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Absent authorization or legal requirement, counselors protect confidentiality and do not release records."}, {"id": "q378", "text": "Ethical multiple relationships are evaluated primarily based on:", "options": ["Whether the counselor finds them convenient.", "Potential for impairment of judgment, exploitation, and harm versus benefit, with informed consent and documentation.", "Whether other counselors do it on TV.", "Only the fee amount."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Risk of exploitation and impaired objectivity is central to dual/multiple relationship decisions."}, {"id": "q379", "text": "Which action best demonstrates ethical gatekeeping in counselor education/supervision?", "options": ["Passing impaired trainees to avoid conflict.", "Addressing trainee competence problems through remediation, documentation, and due process as needed to protect clients.", "Publicly shaming trainees on social media.", "Ignoring skill deficits until licensure."], "correct": 1, "domain": "Professional Practice and Ethics", "explanation": "Gatekeeping protects clients by ensuring trainees meet competence standards through fair, documented processes."}, {"id": "q380", "text": "Content validity is primarily concerned with:", "options": ["Whether scores predict job performance next year.", "Whether test items adequately sample the domain of interest.", "Test-retest stability only.", "Examinee liking for the test booklet."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Content validity addresses representativeness of items relative to the content domain."}, {"id": "q381", "text": "A reliability coefficient of .40 for a high-stakes clinical decision instrument suggests:", "options": ["Excellent precision for individual decisions.", "Substantial measurement error; interpret scores cautiously and avoid overreliance.", "Perfect validity.", "No need for confidence intervals."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Low reliability implies large error; high-stakes interpretations require adequate reliability."}, {"id": "q382", "text": "Which scale of measurement allows meaningful ratios and a true zero?", "options": ["Nominal.", "Ordinal.", "Interval.", "Ratio."], "correct": 3, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Ratio scales have equal intervals and a true zero (e.g., reaction time, weight)."}, {"id": "q383", "text": "The primary purpose of a mental status examination is to:", "options": ["Replace all psychometric testing.", "Describe current cognitive, emotional, and behavioral functioning systematically.", "Determine lifetime personality structure only.", "Provide a career profile."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "The MSE is a structured cross-sectional description of present functioning."}, {"id": "q384", "text": "Which finding most strongly suggests need to assess for mania?", "options": ["Occasional sadness after loss.", "Decreased need for sleep, grandiosity, pressured speech, and risky behavior lasting days.", "Mild worry about a test.", "Preference for routine."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Mania involves elevated/irritable mood with increased energy/activity and associated symptoms over a period of days."}, {"id": "q385", "text": "False negatives on a depression screener mean:", "options": ["People without depression are flagged positive.", "People who have depression are missed by the screener.", "The test has perfect sensitivity.", "Norms are irrelevant."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "A false negative fails to detect a condition that is actually present (missed case)."}, {"id": "q386", "text": "Which interview style is most structured?", "options": ["Open conversational check-in only.", "A standardized diagnostic interview with prescribed questions and scoring rules.", "Free association without prompts.", "Silent observation only."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Structured interviews use standardized questions and decision rules to improve reliability."}, {"id": "q387", "text": "Base rate is important in assessment because:", "options": ["It never affects predictive accuracy.", "The prevalence of a condition influences how predictive a positive/negative test result is.", "It replaces reliability coefficients.", "It only matters for career tests."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Predictive value depends on prevalence/base rates as well as sensitivity and specificity."}, {"id": "q388", "text": "Which is the best example of an aptitude test purpose?", "options": ["Measuring preferred leisure activities only.", "Estimating potential to learn or perform in a domain with training.", "Diagnosing personality disorders exclusively.", "Recording blood pressure."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Aptitude assessment estimates capacity to develop skills or succeed in particular areas."}, {"id": "q389", "text": "A client scores two standard deviations above the mean on a normally distributed test. Approximate percentile is:", "options": ["50th.", "84th.", "98th.", "16th."], "correct": 2, "domain": "Intake, Assessment, and Diagnosis", "explanation": "About 98% of scores fall below +2 SD in a normal distribution."}, {"id": "q390", "text": "Which assessment is most appropriate for immediate suicide risk?", "options": ["A lengthy career interest inventory only.", "Direct inquiry about ideation, plan, intent, means, history, protective factors, and current safety.", "Avoiding the topic to not plant ideas.", "Only projective drawings."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Suicide risk assessment requires direct, thorough inquiry and safety evaluation."}, {"id": "q391", "text": "Criterion-referenced interpretation emphasizes:", "options": ["Standing relative to a norm group only.", "Performance against a defined standard or learning objective.", "Random cutoffs without rationale.", "Counselor intuition exclusively."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Criterion-referenced scores indicate mastery relative to a standard rather than rank in a group."}, {"id": "q392", "text": "Which DSM principle is most accurate?", "options": ["Symptoms alone without context always equal a disorder.", "Diagnosis considers clinically significant disturbance, duration, impairment/distress, and differential considerations.", "Culture never influences symptom expression.", "Personality functioning is irrelevant to all diagnoses."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Diagnosis integrates symptoms, duration, impairment, differentials, and contextual factors."}, {"id": "q393", "text": "Internal consistency reliability is often estimated with:", "options": ["Test-retest over 10 years only.", "Coefficient alpha (or related indices) based on item interrelationships.", "Face validity polls.", "Interviewer charisma ratings."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Internal consistency reflects how consistently items on a test measure the same construct."}, {"id": "q394", "text": "A client appears sedated, with slowed speech and poor concentration after starting a new medication. The counselor should:", "options": ["Ignore medical factors.", "Assess safety, document observations, and coordinate with the prescriber as appropriate with authorization.", "Increase session length to force alertness.", "Diagnose malingering immediately."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Medication side effects can mimic or worsen psychiatric symptoms and require collaborative medical attention."}, {"id": "q395", "text": "Which statement about projective tests is most balanced for NCE-level practice?", "options": ["They provide perfectly objective scores with no interpretation.", "They may yield clinical hypotheses but often have contested psychometric properties and require cautious use.", "They replace structured interviews entirely.", "They are illegal in all settings."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Projectives can generate hypotheses but typically require careful, limited interpretation given psychometric limitations."}, {"id": "q396", "text": "Functional assessment of behavior often identifies:", "options": ["Only IQ scores.", "Antecedents, behaviors, and consequences maintaining a problem pattern.", "Unconscious drives exclusively.", "Zodiac signs."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "ABC functional assessment links context and reinforcement contingencies to problem behaviors."}, {"id": "q397", "text": "Which is a biopsychosocial assessment element?", "options": ["Only spiritual history in isolation.", "Biological, psychological, and social contributors to the presenting problem.", "Only employment status.", "Only favorite color."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Biopsychosocial assessment integrates medical/biological, psychological, and social/contextual domains."}, {"id": "q398", "text": "Malingering differs from factitious disorder primarily in that malingering involves:", "options": ["Unconscious symptom production only.", "Intentional symptom production motivated by external incentives.", "No intentionality.", "Always a psychotic process."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Malingering is intentional feigning for external secondary gain; factitious disorder is driven by the sick role without obvious external rewards."}, {"id": "q399", "text": "Which cognitive screening concern is most urgent?", "options": ["Mild tip-of-the-tongue moments in healthy aging.", "Sudden confusion, disorientation, and fluctuating alertness suggesting possible delirium.", "Preferring written homework.", "Disliking puzzles."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Acute fluctuating confusion raises concern for delirium and medical emergency evaluation."}, {"id": "q400", "text": "Convergent validity evidence is shown when:", "options": ["A test correlates strongly with measures of the same construct.", "A test correlates zero with everything.", "Items look pretty.", "Two raters disagree completely."], "correct": 0, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Convergent validity is supported by correlations with similar constructs/measures."}, {"id": "q401", "text": "Discriminant (divergent) validity is supported when:", "options": ["A depression scale correlates extremely highly with a completely unrelated motor-speed test without explanation.", "A depression scale shows lower correlations with measures of dissimilar constructs than with depression measures.", "All tests intercorrelate at 1.0.", "Reliability is ignored."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Discriminant validity requires measures not to correlate highly with unrelated constructs."}, {"id": "q402", "text": "Which intake area is essential for almost all first sessions?", "options": ["Client's celebrity endorsements.", "Presenting problem, history, risk, functioning, supports, and goals.", "Only favorite movies.", "Only handwriting samples."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Core intake covers problem definition, history, risk, functioning, resources, and treatment goals."}, {"id": "q403", "text": "A bilingual client requests assessment in their preferred language. Best practice is to:", "options": ["Insist on English only for convenience.", "Provide linguistically appropriate assessment or qualified interpretation and consider language effects on results.", "Use a child's classmate as interpreter.", "Skip assessment entirely."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Language-appropriate assessment improves validity and ethics; interpretation quality matters."}, {"id": "q404", "text": "Which best defines sensitivity of a diagnostic test?", "options": ["Probability that a person without the disorder tests negative.", "Probability that a person with the disorder tests positive.", "Overall base rate.", "Interrater agreement only."], "correct": 1, "domain": "Intake, Assessment, and Diagnosis", "explanation": "Sensitivity is the true positive rate among those who have the condition."}, {"id": "q405", "text": "SMART goals are designed to be:", "options": ["Vague and inspirational only.", "Specific, measurable, achievable, relevant, and time-bound.", "Secret from the client.", "Unrelated to assessment data."], "correct": 1, "domain": "Treatment Planning", "explanation": "SMART criteria make goals trackable and clinically useful."}, {"id": "q406", "text": "The primary purpose of a problem list in a treatment plan is to:", "options": ["List every life event without prioritization.", "Identify and prioritize clinically relevant issues guiding interventions.", "Replace diagnosis and goals.", "Satisfy curiosity only."], "correct": 1, "domain": "Treatment Planning", "explanation": "Problem lists organize and prioritize targets for intervention."}, {"id": "q407", "text": "Which is the best initial objective for severe panic with avoidance?", "options": ["Eliminate all anxiety forever in one session.", "Develop a collaborative hierarchy and begin graded exposure with coping skills over defined weeks.", "Only discuss childhood for six months first in all cases.", "Avoid any discussion of panic cues."], "correct": 1, "domain": "Treatment Planning", "explanation": "Anxiety plans often combine psychoeducation, coping skills, and graded exposure with measurable steps."}, {"id": "q408", "text": "Level-of-care decisions should be based primarily on:", "options": ["Counselor convenience.", "Risk, severity, supports, functioning, and least restrictive appropriate setting.", "What looks impressive on marketing materials.", "Only client preference without safety assessment."], "correct": 1, "domain": "Treatment Planning", "explanation": "Care level matches clinical severity and safety while preferring the least restrictive effective setting."}, {"id": "q409", "text": "A treatment plan that lists interventions without goals is weak because:", "options": ["Interventions never matter.", "Goals define desired outcomes that give interventions purpose and allow evaluation.", "Goals are only for research studies.", "Clients dislike progress."], "correct": 1, "domain": "Treatment Planning", "explanation": "Goals specify outcomes; interventions are means toward those outcomes."}, {"id": "q410", "text": "When progress stalls, an evidence-informed next step is to:", "options": ["Continue the same plan indefinitely without review.", "Reassess alliance, goals, barriers, diagnosis, and intervention fit; then revise the plan.", "Blame the client and terminate without discussion.", "Add random techniques weekly without rationale."], "correct": 1, "domain": "Treatment Planning", "explanation": "Stalled progress prompts systematic review of alliance, case formulation, and plan fit."}, {"id": "q411", "text": "Psychoeducation belongs in treatment planning when it:", "options": ["Replaces all therapy forever.", "Helps clients understand symptoms, rationale for interventions, and self-management skills.", "Is used to lecture clients into submission.", "Avoids any collaborative discussion."], "correct": 1, "domain": "Treatment Planning", "explanation": "Psychoeducation supports engagement, adherence, and skill building when matched to client needs."}, {"id": "q412", "text": "Which is a reasonable short-term goal for major depression in outpatient care?", "options": ["Completely rewrite personality in two weeks.", "Increase behavioral activation to three valued activities per week and reduce PHQ-9 by a defined amount in 6–8 weeks.", "Never feel sad again.", "Only explore dreams without behavioral targets."], "correct": 1, "domain": "Treatment Planning", "explanation": "Short-term goals should be realistic, measurable, and linked to evidence-based strategies."}, {"id": "q413", "text": "Informed consent intersects treatment planning when counselors:", "options": ["Hide the plan from clients.", "Collaborate on goals/interventions and discuss risks, benefits, and alternatives.", "Force a single theoretical approach without explanation.", "Refuse to discuss expected duration."], "correct": 1, "domain": "Treatment Planning", "explanation": "Collaborative planning is part of ongoing informed consent and shared decision-making."}, {"id": "q414", "text": "Case formulation differs from diagnosis by:", "options": ["Being identical in all systems.", "Explaining how factors maintain problems and guiding individualized intervention selection.", "Ignoring assessment data.", "Only listing ICD codes."], "correct": 1, "domain": "Treatment Planning", "explanation": "Formulation is an explanatory map connecting assessment to treatment choices."}, {"id": "q415", "text": "Which element is most important in safety planning?", "options": ["A vague suggestion to 'stay positive.'", "Warning signs, coping strategies, social/professional supports, means reduction, and crisis contacts.", "Only the counselor's personal cell for non-crisis chats.", "A promise that crises will not occur."], "correct": 1, "domain": "Treatment Planning", "explanation": "Safety plans are concrete, collaborative, and include means safety and crisis resources."}, {"id": "q416", "text": "Cultural adaptation of a treatment plan may include:", "options": ["Ignoring cultural values as irrelevant.", "Modifying language, metaphors, family involvement, and goals to fit client cultural context while preserving core effective elements.", "Using stereotypes as the entire plan.", "Refusing interpreters."], "correct": 1, "domain": "Treatment Planning", "explanation": "Cultural adaptation improves fit and engagement without abandoning effective core components."}, {"id": "q417", "text": "A parallel process in supervision that affects treatment planning is best handled by:", "options": ["Ignoring it.", "Identifying it in supervision and using insight to improve clinical decision-making with the client.", "Acting out the same conflict with the client intentionally.", "Terminating supervision."], "correct": 1, "domain": "Treatment Planning", "explanation": "Recognizing parallel process in supervision can refine the counselor's planning and relational work."}, {"id": "q418", "text": "Which discharge plan component is most essential?", "options": ["No follow-up resources.", "Relapse prevention, aftercare/referrals, medication coordination as relevant, and crisis instructions.", "Only a goodbye card.", "Deleting all records same day."], "correct": 1, "domain": "Treatment Planning", "explanation": "Discharge planning supports continuity, relapse prevention, and safe transitions."}, {"id": "q419", "text": "Session frequency decisions should consider:", "options": ["Only office vacancy rates.", "Symptom severity, risk, treatment phase, client preference, and practical constraints.", "A single universal rule for all clients.", "Only insurance maximums without clinical judgment."], "correct": 1, "domain": "Treatment Planning", "explanation": "Frequency is individualized based on clinical need and constraints."}, {"id": "q420", "text": "An objective written for skill building is strongest when it includes:", "options": ["'Client will do better.'", "Observable skill, practice frequency, and criterion for success within a timeframe.", "Only the counselor's theory name.", "No evaluation method."], "correct": 1, "domain": "Treatment Planning", "explanation": "Skill objectives specify observable behaviors and success criteria."}, {"id": "q421", "text": "When a client prefers a non-evidence-based approach that is not harmful, the counselor should:", "options": ["Ridicule the preference.", "Discuss evidence, risks/benefits, and collaboratively integrate preferences when ethically and clinically appropriate.", "Refuse any collaboration.", "Silently substitute without telling the client."], "correct": 1, "domain": "Treatment Planning", "explanation": "Shared decision-making respects preferences while providing honest information about evidence and fit."}, {"id": "q422", "text": "Treatment plans for co-occurring substance use and depression should:", "options": ["Treat only one issue and ignore the other.", "Integrate assessment and interventions for both conditions, sequencing based on risk and readiness.", "Assume substances never affect mood.", "Delay all depression care until lifelong abstinence is proven."], "correct": 1, "domain": "Treatment Planning", "explanation": "Co-occurring disorders benefit from integrated planning rather than siloed neglect."}, {"id": "q423", "text": "Which metric best evaluates goal attainment for social anxiety exposure work?", "options": ["Counselor intuition only.", "Completed hierarchy steps, SUDS trends, and functional approach behavior in target situations.", "Only session attendance.", "Only number of worksheets printed."], "correct": 1, "domain": "Treatment Planning", "explanation": "Exposure progress is tracked via hierarchy completion, distress ratings, and real-world functioning."}, {"id": "q424", "text": "A counselor includes advocacy goals in a plan when:", "options": ["The counselor wants political credit.", "Systemic barriers are central to client welfare and advocacy is appropriate to the counselor role and client consent.", "The client forbids any systems discussion but the counselor insists for personal reasons.", "It replaces all clinical care always."], "correct": 1, "domain": "Treatment Planning", "explanation": "Advocacy can be part of counseling when systemic barriers affect welfare and actions stay within role and consent."}, {"id": "q425", "text": "Which is the best example of a maintenance-phase goal?", "options": ["Initial crisis stabilization only.", "Consolidate skills, prevent relapse, and generalize gains to new contexts over 8 weeks.", "First-time diagnostic clarification only.", "Establishing whether counseling is needed."], "correct": 1, "domain": "Treatment Planning", "explanation": "Maintenance focuses on consolidating gains and preventing relapse after acute improvement."}, {"id": "q426", "text": "Documentation of medical necessity typically connects:", "options": ["Services provided to diagnosed conditions, impairment, and planned interventions.", "The counselor's favorite theory without client problems.", "Only the weather.", "Gossip about family members not in treatment."], "correct": 0, "domain": "Treatment Planning", "explanation": "Medical necessity links functional impairment and diagnosis to services and goals."}, {"id": "q427", "text": "If a client repeatedly no-shows, the plan should address:", "options": ["Nothing; ignore engagement.", "Barriers, alliance, motivation, scheduling fit, and a clear attendance/re-engagement policy.", "Immediate permanent ban without discussion in all cases.", "Raising fees only as punishment without conversation."], "correct": 1, "domain": "Treatment Planning", "explanation": "Engagement problems are clinical data requiring collaborative problem-solving and clear policies."}, {"id": "q428", "text": "Which planning approach best fits brief solution-focused counseling?", "options": ["Long personality reconstruction as the sole aim.", "Preferred future, exceptions, small measurable steps, and client strengths.", "Only free association.", "Mandatory daily flooding for all problems."], "correct": 1, "domain": "Treatment Planning", "explanation": "Solution-focused planning emphasizes preferred future, exceptions, and incremental change."}, {"id": "q429", "text": "Attending behavior typically includes:", "options": ["Checking email during sessions.", "Appropriate eye contact, body posture, following, and psychological presence.", "Constant advice-giving.", "Interrupting every sentence."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Attending communicates presence through nonverbal and verbal following behaviors."}, {"id": "q430", "text": "A paraphrase primarily:", "options": ["Adds a new interpretation the client did not imply.", "Restates the client's content in fresh words to check understanding.", "Changes the subject.", "Provides a diagnosis."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Paraphrase mirrors content to confirm understanding without adding deep interpretation."}, {"id": "q431", "text": "Which is the best example of a feeling reflection?", "options": ["You went to the store yesterday.", "You're feeling overwhelmed and scared about the upcoming changes.", "Have you tried yoga?", "That is illogical."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Feeling reflections name the client's affect to convey empathy and deepen awareness."}, {"id": "q432", "text": "Closed questions are most useful when the counselor needs:", "options": ["Long narrative exploration only.", "Specific facts, yes/no clarity, or focused details efficiently.", "To silence the client permanently.", "To avoid all structure."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Closed questions efficiently gather specific data; open questions invite elaboration."}, {"id": "q433", "text": "The skill of clarifying is used to:", "options": ["Confuse the client.", "Resolve ambiguity and ensure accurate understanding of the client's message.", "End the session early.", "Impose the counselor's story."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Clarifying questions/statements reduce misunderstanding of vague or complex material."}, {"id": "q434", "text": "In CBT, a thought record typically helps clients:", "options": ["Ignore thoughts completely.", "Identify situations, automatic thoughts, emotions, evidence, and alternative responses.", "Only track calories.", "Diagnose others."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Thought records structure cognitive assessment and restructuring practice between sessions."}, {"id": "q435", "text": "Exposure and response prevention (ERP) is most associated with treating:", "options": ["OCD-related rituals by facing cues without performing compulsions.", "Only career indecision.", "Only intellectual disability.", "Only insomnia with sleep restriction exclusively."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "ERP is a first-line behavioral treatment for OCD involving exposure without ritualizing."}, {"id": "q436", "text": "Which Yalom therapeutic factor involves learning from others' feedback in group?", "options": ["Universality only.", "Interpersonal learning.", "Existential factors only.", "Recapitulation of family is never a factor."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Interpersonal learning includes insight and new relational experiences through member feedback and interaction."}, {"id": "q437", "text": "A counselor says, 'On one hand you want to leave the job, and on the other you fear financial instability.' This is:", "options": ["A confrontation of discrepancy / double-sided reflection.", "A closed question.", "A diagnosis.", "A homework assignment."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Double-sided reflections capture ambivalence and discrepancies constructively, common in MI and advanced empathy."}, {"id": "q438", "text": "Token economies are based primarily on:", "options": ["Operant conditioning principles of reinforcement.", "Classical free association.", "Empty-chair dialogue.", "Genogram construction only."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Token economies systematically reinforce target behaviors using secondary reinforcers."}, {"id": "q439", "text": "Which intervention is most consistent with acceptance and commitment therapy (ACT)?", "options": ["Eliminating all private experiences.", "Building psychological flexibility through acceptance, defusion, values, and committed action.", "Only disputing with harsh labels.", "Ignoring values."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "ACT fosters psychological flexibility rather than experiential avoidance as the main aim."}, {"id": "q440", "text": "Linking in group counseling means:", "options": ["Isolating members from one another.", "Connecting members' themes or experiences to promote cohesion and universality.", "Only talking to the leader.", "Ending group permanently."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Linking highlights commonalities and interpersonal connections among members."}, {"id": "q441", "text": "Which is a risk of premature advice-giving?", "options": ["It always builds autonomy.", "It can foster dependency, miss key data, and weaken client agency.", "It is identical to collaboration.", "It never affects alliance."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Early advice may short-circuit exploration and reduce client ownership of solutions."}, {"id": "q442", "text": "Role-play in counseling is often used to:", "options": ["Humiliate clients.", "Practice new interpersonal skills and prepare for real-life situations in a safe setting.", "Replace all talk therapy forever.", "Diagnose psychosis."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Behavioral rehearsal via role-play builds skills and confidence before real-world application."}, {"id": "q443", "text": "Which best describes a genogram's clinical use?", "options": ["Measuring blood glucose.", "Mapping multigenerational family patterns, relationships, and significant events.", "Only listing coworkers.", "Scoring IQ."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Genograms visualize family structure and patterns across generations for assessment and intervention."}, {"id": "q444", "text": "Socratic questioning in CBT aims to:", "options": ["Trick clients into agreeing with the counselor.", "Guide clients to examine evidence and generate alternative perspectives through guided discovery.", "Avoid cognitive content.", "Provide only lectures."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Socratic dialogue promotes guided discovery rather than didactic imposition of beliefs."}, {"id": "q445", "text": "Which group stage is characterized by conflict, dominance struggles, and resistance?", "options": ["Orientation/forming only.", "Transition/storming.", "Termination only.", "Pre-group screening only."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "The transition/storming stage often includes conflict and testing of norms and leadership."}, {"id": "q446", "text": "Mindfulness-based interventions primarily train clients to:", "options": ["Ruminate more efficiently.", "Pay nonjudgmental attention to present-moment experience.", "Suppress all thoughts permanently.", "Avoid bodily sensations always."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Mindfulness cultivates present-centered, nonjudgmental awareness."}, {"id": "q447", "text": "A counselor uses 'when you look away each time we discuss anger…' This skill is:", "options": ["Immediacy / process comment.", "Career assessment.", "A projective test.", "A validity scale."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Process comments/immediacy address here-and-now behavior in the therapeutic relationship."}, {"id": "q448", "text": "Which is most characteristic of feminist counseling interventions?", "options": ["Ignoring power and gender.", "Attention to power, egalitarianism, social context, and empowerment.", "Strict hierarchy with expert domination.", "Avoiding any discussion of culture."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Feminist approaches emphasize power analysis, egalitarian relationship, and empowerment."}, {"id": "q449", "text": "Contingency contracts in counseling specify:", "options": ["Unclear expectations.", "Agreed behaviors and consequences/reinforcers for meeting or not meeting targets.", "Only counselor duties.", "Dream symbols."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Contingency contracts make behavioral expectations and consequences explicit and collaborative."}, {"id": "q450", "text": "Which response best demonstrates advanced empathy?", "options": ["That must be hard (said routinely without fit).", "It seems part of you wants closeness, while another part expects rejection if you reach out—leaving you stuck and lonely.", "Just get over it.", "Have you tried not feeling that?"], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Advanced empathy captures deeper, often unspoken meanings and conflicts with accuracy and care."}, {"id": "q451", "text": "Flooding as an exposure method involves:", "options": ["Very gradual hierarchy only.", "Prolonged exposure to high-intensity feared stimuli without escape, when clinically appropriate.", "Avoidance homework.", "Only imaginal career fantasies."], "correct": 1, "domain": "Counseling Skills and Interventions", "explanation": "Flooding uses intense prolonged exposure; it requires careful selection, consent, and competence."}, {"id": "q452", "text": "Which intervention targets family enmeshment in structural therapy?", "options": ["Strengthening diffuse boundaries and supporting appropriate subsystem differentiation.", "Increasing triangulation intentionally.", "Removing all rules permanently.", "Only individual free association."], "correct": 0, "domain": "Counseling Skills and Interventions", "explanation": "Structural work clarifies boundaries and strengthens appropriate subsystem functioning when enmeshment is present."}, {"id": "q453", "text": "According to Erikson, the psychosocial crisis of generativity vs. stagnation is typical of:", "options": ["Infancy.", "Adolescence.", "Middle adulthood.", "Only late adulthood."], "correct": 2, "domain": "Areas of Clinical Focus", "explanation": "Generativity vs. stagnation is associated with middle adulthood and concern for guiding the next generation."}, {"id": "q454", "text": "Vygotsky's zone of proximal development refers to:", "options": ["Tasks a learner can do only with no help and no challenge.", "The range between independent performance and performance with guided support.", "Genetic IQ fixed at birth.", "Only motor reflexes."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "ZPD is the gap between solo capability and capability with scaffolding from a more knowledgeable other."}, {"id": "q455", "text": "Which career theory emphasizes matching traits to occupational factors?", "options": ["Trait-and-factor / person-environment fit approaches (e.g., Parsons, Holland-related fitting).", "Only pure existential counseling.", "Only Gestalt unfinished business.", "Classical conditioning of job titles."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Trait-and-factor approaches assess individual traits and match them to job requirements/environments."}, {"id": "q456", "text": "The concept of career adaptability is most associated with:", "options": ["Savickas and career construction perspectives emphasizing coping with career tasks and transitions.", "Only Holland codes without development.", "Ignoring life themes.", "Fixed matching at age 16 only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Career construction/adaptability focuses on how people navigate career tasks, transitions, and trauma."}, {"id": "q457", "text": "Which symptom cluster is most characteristic of PTSD?", "options": ["Only increased appetite.", "Intrusion, avoidance, negative alterations in cognition/mood, and arousal/reactivity after trauma.", "Only lifelong schizoid detachment without trauma.", "Mild preference for solitude."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "PTSD includes intrusion, avoidance, negative cognition/mood changes, and hyperarousal after qualifying trauma."}, {"id": "q458", "text": "Motivational interviewing is especially useful for clients who are:", "options": ["Fully decided and finished with change.", "Ambivalent about behavior change.", "Unable to speak.", "Seeking only IQ testing."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "MI is designed to work with ambivalence and strengthen intrinsic motivation for change."}, {"id": "q459", "text": "Which best describes minority stress?", "options": ["Stress unrelated to identity.", "Chronic stress from stigma, prejudice, and discrimination experienced by marginalized groups.", "Only acute medical pain.", "A formal thought disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Minority stress theory links excess stress from social stigma to mental health disparities."}, {"id": "q460", "text": "In addiction counseling, harm reduction approaches primarily aim to:", "options": ["Require immediate lifelong abstinence as the only acceptable goal for every client.", "Reduce substance-related harm and engage clients at their readiness level.", "Ignore safety entirely.", "Shame clients into change."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Harm reduction meets clients where they are to reduce negative consequences and support engagement."}, {"id": "q461", "text": "Which childhood disorder category involves persistent pattern of violating others' rights or major norms?", "options": ["Specific phobia.", "Conduct disorder.", "Selective mutism only.", "Enuresis only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Conduct disorder features repetitive behavior that violates rights of others or age-appropriate norms."}, {"id": "q462", "text": "A client with somatic symptom concerns repeatedly fears serious illness despite medical reassurance. Counseling focus often includes:", "options": ["Only more unnecessary invasive tests ordered by the counselor.", "Anxiety, health-related beliefs, functioning, and coordinated care with medical providers.", "Ignoring distress as fake always.", "Forcing a single diagnosis of malingering."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Somatic symptom work addresses health anxiety, beliefs, functioning, and collaborative medical care."}, {"id": "q463", "text": "Which is a key feature of burnout among counselors?", "options": ["Increased energy and idealism only.", "Emotional exhaustion, cynicism/depersonalization, and reduced sense of efficacy.", "Perfect work-life balance.", "Only physical fitness gains."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Burnout involves exhaustion, depersonalization/cynicism, and diminished professional accomplishment."}, {"id": "q464", "text": "Gender-affirming counseling practice includes:", "options": ["Conversion efforts.", "Respecting affirmed name/pronouns, exploring identity supportively, and addressing minority stress.", "Forcing disclosure to all family immediately.", "Assuming identity is the sole cause of all symptoms always."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Affirmative care respects identity and addresses related stressors without pathologizing identity itself."}, {"id": "q465", "text": "Which couple pattern involves one partner seeking closeness while the other withdraws?", "options": ["Pursuer–distancer dynamics.", "Perfect synchrony always.", "Only parallel play in children.", "Unrelated to attachment."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Pursuer–distancer cycles are common complementary patterns in distressed couples."}, {"id": "q466", "text": "Learned helplessness is most associated with:", "options": ["Belief that outcomes are uncontrollable after repeated failure experiences, linked to depression research.", "High self-efficacy always.", "Only manic grandiosity.", "Career inventiveness only."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Learned helplessness describes passive responding after uncontrollable aversive events and relates to depression models."}, {"id": "q467", "text": "Which developmental concept describes adolescents' belief that others are as focused on them as they are on themselves?", "options": ["Imaginary audience.", "Object permanence.", "Conservation.", "Secure base only in infancy."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "Imaginary audience is an adolescent egocentrism concept (Elkind) about perceived scrutiny by others."}, {"id": "q468", "text": "Primary prevention in counseling aims to:", "options": ["Treat only chronic severe disorders after disability is entrenched.", "Reduce incidence of problems by targeting well populations before onset.", "Provide tertiary rehabilitation only.", "Ignore community factors."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Primary prevention seeks to prevent problems before they occur in at-risk or general populations."}, {"id": "q469", "text": "Which statement about grief is most accurate?", "options": ["All grief follows five fixed stages in order for everyone.", "Grief is variable; cultural norms, relationship, and meaning shape expression and course.", "Grief never involves yearning.", "Counseling should force rapid closure."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Contemporary grief models emphasize variability and cultural context rather than rigid universal stages."}, {"id": "q470", "text": "A client with ADHD reports workplace underperformance. Clinical focus may include:", "options": ["Only personality assassination.", "Executive functioning supports, environmental modifications, skills, and possible medical collaboration.", "Ignoring accommodations as coddling.", "Assuming laziness without assessment."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Adult ADHD care often targets executive skills, structure, and collaborative treatment options."}, {"id": "q471", "text": "Which research design best supports causal inference about an intervention's effect?", "options": ["Anecdote.", "Well-controlled randomized experiment.", "Single correlational survey only.", "Uncontrolled case opinion only."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Randomized controlled designs best support causal claims about treatment efficacy."}, {"id": "q472", "text": "External validity refers to:", "options": ["Whether results generalize beyond the study conditions/sample.", "Whether the independent variable caused the outcome inside the study.", "Scorer agreement only.", "Item wording beauty."], "correct": 0, "domain": "Areas of Clinical Focus", "explanation": "External validity is generalizability; internal validity concerns causal interpretability within the study."}, {"id": "q473", "text": "Which anxiety disorder is characterized by recurrent unexpected panic attacks with persistent concern/change in behavior?", "options": ["Specific phobia limited to one object without panic history necessarily.", "Panic disorder.", "Selective mutism only.", "Oppositional defiant disorder."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Panic disorder involves recurrent unexpected panic attacks plus worry or maladaptive change related to attacks."}, {"id": "q474", "text": "Spiritual/religious assessment in counseling is appropriate when:", "options": ["The counselor imposes a belief system.", "Spirituality may be a source of meaning, coping, conflict, or identity for the client and is explored respectfully.", "It replaces all ethical codes.", "It is used to proselytize."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Spiritually responsive counseling explores client spirituality as potentially relevant without imposition."}, {"id": "q475", "text": "Which best describes circular causality in family systems?", "options": ["One person is solely to blame in a linear chain always.", "Mutual influence patterns in which each person's behavior shapes and is shaped by others' responses.", "Genetics only.", "Random unrelated events."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "Systems thinking emphasizes reciprocal, ongoing influence rather than simple linear blame."}, {"id": "q476", "text": "A school counselor coordinating services for a student with disabilities is most clearly engaged in:", "options": ["Only private long-term psychoanalysis.", "Advocacy and systems-level support within educational contexts.", "Forensic evaluation for criminal court only.", "Prescribing medication."], "correct": 1, "domain": "Areas of Clinical Focus", "explanation": "School counseling often includes educational advocacy and coordination within systems of care."}, {"id": "q477", "text": "Congruence in the counselor means:", "options": ["Saying everything without filters.", "Alignment between inner experience and outward professional communication in a helpful way.", "Never having emotions.", "Copying the client's posture only as mimicry without presence."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Congruence is genuine, integrated presence within professional boundaries."}, {"id": "q478", "text": "Which attribute most supports ethical decision-making under pressure?", "options": ["Impulsivity.", "Moral courage and commitment to client welfare over personal comfort.", "People-pleasing at any cost.", "Avoidance of codes of ethics."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Moral courage helps counselors act ethically despite pressure, fear, or inconvenience."}, {"id": "q479", "text": "Empathic accuracy is best described as:", "options": ["Projecting the counselor's feelings onto the client.", "Correctly understanding the client's internal experience.", "Finishing the client's sentences always.", "Agreeing with all content."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Empathic accuracy is the degree to which the counselor correctly perceives the client's thoughts/feelings."}, {"id": "q480", "text": "A nondefensive stance when receiving client anger most reflects:", "options": ["Fragility.", "Emotional regulation, humility, and alliance repair capacity.", "Agreement that the counselor is always wrong.", "Immediate counterattack."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Regulated, nondefensive responding supports safety and repair when clients express anger."}, {"id": "q481", "text": "Professional diligence includes:", "options": ["Chronic lateness.", "Thorough preparation, follow-through on commitments, and careful clinical work.", "Skipping documentation.", "Ignoring emails about risk for weeks."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Diligence is careful, reliable, and thorough professional practice."}, {"id": "q482", "text": "Which quality helps counselors avoid burnout-related ethical slips?", "options": ["Endless overwork without limits.", "Self-awareness of impairment and willingness to adjust load and seek support.", "Isolation and secrecy about stress.", "Caffeine only."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Recognizing impairment early and seeking support protects clients and counselors."}, {"id": "q483", "text": "Respect in counseling is demonstrated when the counselor:", "options": ["Mocks client dialect.", "Honors dignity, culture, and autonomy even during disagreement.", "Uses sarcasm to motivate.", "Imposes nicknames without consent."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Respect upholds client dignity and autonomy across differences and conflict."}, {"id": "q484", "text": "Which attribute is most tied to maintaining confidentiality habits day to day?", "options": ["Curiosity about gossip.", "Conscientiousness and habitual privacy discipline.", "Forgetfulness about chart security.", "Public processing of cases for fun."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Conscientious privacy habits operationalize confidentiality ethics in daily behavior."}, {"id": "q485", "text": "Therapeutic optimism differs from toxic positivity in that it:", "options": ["Denies pain.", "Holds realistic hope while validating suffering and constraints.", "Guarantees outcomes.", "Avoids hard topics."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Healthy hope validates difficulty while supporting possibility; toxic positivity invalidates pain."}, {"id": "q486", "text": "A counselor who can laugh gently with a client at appropriate moments may be showing:", "options": ["Boundary-less chaos always.", "Human warmth and relational flexibility within professional judgment.", "Incompetence.", "Avoidance of all affect."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Appropriate shared humor can strengthen alliance when attuned and respectful."}, {"id": "q487", "text": "Self-reflection after sessions primarily supports:", "options": ["Rumination without learning.", "Professional growth, countertransference awareness, and improved future interventions.", "Only self-criticism.", "Billing fraud."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Reflective practice turns experience into learning and safer, more effective care."}, {"id": "q488", "text": "Which attribute best describes fairness in allocating time and resources among clients?", "options": ["Favoritism toward easy clients.", "Justice-oriented equity and consistent professional standards.", "Ignoring high-risk clients.", "Random cancellation patterns."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Justice involves fair, non-discriminatory treatment and equitable professional conduct."}, {"id": "q489", "text": "Emotional availability means the counselor:", "options": ["Is flooded and uncontained every session.", "Can be present with client affect while remaining regulated and boundaried.", "Avoids all emotion.", "Requires the client to caretake the counselor."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Availability is present and responsive without role reversal or dysregulation."}, {"id": "q490", "text": "Which behavior shows intellectual humility?", "options": ["Claiming certainty without evidence.", "Revising views when new data or client feedback warrants it.", "Never reading after graduation.", "Dismissing supervision."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Intellectual humility includes openness to correction and limits of knowledge."}, {"id": "q491", "text": "A counselor feels bored with a client and secretly blames the client. Growth-oriented response is to:", "options": ["Express boredom as the client's fault in session one.", "Explore the reaction in supervision as possible countertransference or case stagnation.", "Terminate abruptly via text.", "Yawn loudly each session intentionally."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Boredom can be clinical data; supervision helps interpret and respond professionally."}, {"id": "q492", "text": "Dependability as a counselor attribute is shown by:", "options": ["Frequent unexplained no-shows.", "Keeping appointments, honoring agreements, and communicating changes promptly.", "Changing fees randomly each week without notice.", "Losing records often."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Dependability builds trust through reliability and clear communication."}, {"id": "q493", "text": "Which quality is essential for multicultural orientation?", "options": ["Cultural concealment of all differences.", "Cultural humility, comfort with diversity, and responsiveness to client cultural identity.", "Colorblind denial of culture.", "Stereotyping as efficiency."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Multicultural orientation emphasizes humility, comfort with diversity, and cultural responsiveness."}, {"id": "q494", "text": "Compassion differs from pity in that compassion:", "options": ["Elevates the helper and diminishes the client.", "Joins with suffering while affirming dignity and agency.", "Avoids action entirely.", "Requires rescuing without consent."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Compassion is solidarity with suffering that preserves dignity, unlike pity's hierarchy."}, {"id": "q495", "text": "A counselor admits limits of expertise to a client. This most often reflects:", "options": ["Incompetence only.", "Honesty, humility, and ethical transparency that can strengthen trust.", "A boundary violation.", "Abandonment automatically."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Transparent limits, paired with appropriate help-seeking or referral, support ethical trust."}, {"id": "q496", "text": "Which attribute helps counselors navigate strong political differences with clients?", "options": ["Debate to convert the client.", "Bracketing, respect for autonomy, and focus on the client's goals and welfare.", "Ending therapy for any disagreement.", "Secretly sabotaging goals."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Professional bracketing keeps the work centered on client welfare rather than counselor ideology."}, {"id": "q497", "text": "Mindful self-care is best framed as:", "options": ["Selfish neglect of clients.", "An ethical responsibility that sustains competence and presence.", "Optional only for weak counselors.", "A replacement for clinical skill."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Self-care supports sustainable, ethical practice and client welfare."}, {"id": "q498", "text": "Which best illustrates accountability?", "options": ["Blaming systems for every personal error without change.", "Owning mistakes, repairing harm, and adjusting practice.", "Hiding errors from supervisors.", "Documenting falsely to look better."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Accountability includes ownership, repair, and learning after missteps."}, {"id": "q499", "text": "Gentleness in confrontation means:", "options": ["Avoiding all difficult feedback.", "Delivering necessary honesty with care, timing, and respect.", "Using insults softly.", "Only written feedback never spoken."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Effective confrontation pairs truth with relational care and good timing."}, {"id": "q500", "text": "Which combination best describes professional maturity?", "options": ["Technical skill without ethics.", "Competence, ethical integrity, self-awareness, and relational steadiness under stress.", "Confidence without feedback.", "Experience years alone without growth."], "correct": 1, "domain": "Core Counseling Attributes", "explanation": "Professional maturity integrates skill, ethics, self-awareness, and stable relational presence."}];
